    value: PagoMaestro[K]
  ) =>
    setMaestros(prev =>
      prev.map(m => {
        if (m.id !== maestroId) return m;
        return {
          ...m,
          pagos: m.pagos.map(p => p.id === pagoId ? { ...p, [field]: value } : p),
        };
      })
