  const [selectorOpen, setSelectorOpen] = useState<{ finId: string; desId: string } | null>(null);
  // Vista previa de comprobante
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [uploadTarget, setUploadTarget] = useState<{ finId: string; desId: string } | null>(null);

  // ─── Handlers Financieras ────────────────────────────────────────────────

  const handleAddFinanciera = () => {
    const id = `f${Date.now()}`;
    setFinancieras(prev => [
      ...prev,
      { id, nombre: "Nueva Financiera", expandida: true, desembolsos: [] },
    ]);
  };

  const handleDeleteFinanciera = (finId: string) => {
    setFinancieras(prev => prev.filter(f => f.id !== finId));
  };

  const handleUpdateFinanciera = (finId: string, nombre: string) => {
    setFinancieras(prev =>
      prev.map(f => f.id === finId ? { ...f, nombre } : f)
    );
  };

  const handleToggleExpand = (finId: string) => {
    setFinancieras(prev =>
      prev.map(f => f.id === finId ? { ...f, expandida: !f.expandida } : f)
    );
  };

  // ─── Handlers Desembolsos ─────────────────────────────────────────────────

  const handleAddDesembolso = (finId: string) => {
    const id = `d${Date.now()}`;
    setFinancieras(prev =>
      prev.map(f => {
        if (f.id !== finId) return f;
        return {
          ...f,
          desembolsos: [
            ...f.desembolsos,
            {
              id,
              hito: `Desembolso ${f.desembolsos.length + 1}`,
              fecha: new Date().toISOString().slice(0, 10),
              monto: 10000,
              estado: "Pendiente" as const,
              beneficiariosAsignados: [],
            },
          ],
        };
      })
    );
  };

  const handleUpdateDesembolso = (
    finId: string,
    desId: string,
    field: keyof Desembolso,
    value: unknown
  ) => {
    setFinancieras(prev =>
      prev.map(f => {
        if (f.id !== finId) return f;
        return {
          ...f,
          desembolsos: f.desembolsos.map(d =>
            d.id === desId ? { ...d, [field]: value } : d
          ),
        };
      })
    );
  };

  const handleDeleteDesembolso = (finId: string, desId: string) => {
    setFinancieras(prev =>
      prev.map(f => {
        if (f.id !== finId) return f;
        return { ...f, desembolsos: f.desembolsos.filter(d => d.id !== desId) };
      })
    );
  };

  // ─── Handlers Asignación Beneficiarios ───────────────────────────────────

  const toggleBeneficiario = (finId: string, desId: string, benId: string) => {
    setFinancieras(prev =>
      prev.map(f => {
        if (f.id !== finId) return f;
        return {
          ...f,
          desembolsos: f.desembolsos.map(d => {
            if (d.id !== desId) return d;
            const already = d.beneficiariosAsignados.includes(benId);
            return {
              ...d,
              beneficiariosAsignados: already
                ? d.beneficiariosAsignados.filter(id => id !== benId)
                : [...d.beneficiariosAsignados, benId],
            };
          }),
        };
      })
    );
  };

  // ─── Handlers Comprobante ─────────────────────────────────────────────────

  const handleUploadClick = (finId: string, desId: string) => {
    setUploadTarget({ finId, desId });
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !uploadTarget) return;
    const url = URL.createObjectURL(file);
    handleUpdateDesembolso(uploadTarget.finId, uploadTarget.desId, "comprobante", url);
    // Reset file input so same file can be re-selected
    e.target.value = "";
    setUploadTarget(null);
  };

  // ─── Export to CSV ────────────────────────────────────────────────────────

  const handleExport = () => {
    const rows: string[] = [
      ["FINANCIERA", "HITO", "FECHA", "MONTO (S/)", "ESTADO", "BENEFICIARIOS ASIGNADOS"].join(";"),
    ];
    financieras.forEach(f => {
      f.desembolsos.forEach(d => {
        const benNames = d.beneficiariosAsignados
          .map(id => beneficiarios.find(b => b.id === id)?.postulante || id)
          .join(" | ");
        rows.push(
          [
            `"${f.nombre}"`,
            `"${d.hito}"`,
            d.fecha,
            d.monto,
            d.estado,
            `"${benNames}"`,
          ].join(";")
        );
      });
    });
    const csv = "\uFEFF" + rows.join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `CronogramaPagos_${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
  };

  // ─── Totals ───────────────────────────────────────────────────────────────

  const grandTotal = financieras.flatMap(f => f.desembolsos).reduce((s, d) => s + d.monto, 0);
  const totalDesembolsado = financieras
    .flatMap(f => f.desembolsos)
    .filter(d => d.estado === "Desembolsado")
    .reduce((s, d) => s + d.monto, 0);

  // ─── Render ───────────────────────────────────────────────────────────────

  return (
    <div className="w-full max-w-6xl mx-auto px-4 py-6 space-y-6 animate-in fade-in duration-300">

      {/* Hidden file input */}
      <input
        ref={fileInputRef}
        type="file"
        accept="image/*"
        className="hidden"
        onChange={handleFileChange}
      />

      {/* Image Preview Modal */}
      {previewUrl && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/90 backdrop-blur-md"
          onClick={() => setPreviewUrl(null)}
        >
          <div className="relative max-w-2xl w-full p-4" onClick={e => e.stopPropagation()}>
            <button
              onClick={() => setPreviewUrl(null)}
              className="absolute -top-2 -right-2 p-1.5 bg-slate-800 border border-slate-700 rounded-full text-slate-300 hover:text-white z-10"
            >
              <X className="w-4 h-4" />
            </button>
            <img src={previewUrl} alt="Comprobante" className="w-full rounded-2xl border border-slate-700 shadow-2xl" />
          </div>
        </div>
      )}

      {/* ── Header ── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-6 rounded-3xl bg-slate-900 border border-slate-800 shadow-xl">
        <div className="flex items-center gap-3">
          <div className="p-3 rounded-2xl bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 shadow-md">
            <CreditCard className="w-6 h-6" />
          </div>
          <div>
            <h1 className="text-2xl font-black text-white tracking-tight">Cronograma de Pagos</h1>
            <p className="text-xs text-slate-400">
              Gestión de financieras, desembolsos y asignación de beneficiarios.
            </p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          {/* Totals pill */}
          <div className="bg-slate-950 border border-slate-800 rounded-2xl px-4 py-2 text-right">
            <span className="block text-[10px] text-slate-400 uppercase font-bold">Total recibido / pactado</span>
            <span className="font-black font-mono text-emerald-400">
              S/ {totalDesembolsado.toLocaleString("es-PE", { minimumFractionDigits: 2 })}
            </span>
            <span className="text-slate-500 font-mono text-xs">
              {" "}/ S/ {grandTotal.toLocaleString("es-PE", { minimumFractionDigits: 2 })}
            </span>
          </div>
          <button
            onClick={handleExport}
            className="flex items-center gap-2 bg-emerald-700 hover:bg-emerald-600 text-white font-bold text-xs px-4 py-2.5 rounded-xl transition shadow-lg shadow-emerald-700/20"
          >
            <FileSpreadsheet className="w-4 h-4" /> Exportar
          </button>
          <button
            onClick={handleAddFinanciera}
            className="flex items-center gap-2 bg-sky-600 hover:bg-sky-500 text-white font-bold text-xs px-4 py-2.5 rounded-xl transition shadow-lg shadow-sky-600/20"
          >
            <Plus className="w-4 h-4" /> Nueva Financiera
          </button>
        </div>
      </div>

      {/* ── Financieras ── */}
      {financieras.length === 0 && (
        <div className="p-12 text-center rounded-3xl bg-slate-900 border border-slate-800 text-slate-500 text-sm">
          Sin financieras aún. Haz clic en &ldquo;Nueva Financiera&rdquo; para comenzar.
        </div>
      )}

      {financieras.map(fin => {
        const totalFin = fin.desembolsos.reduce((s, d) => s + d.monto, 0);
        const desembFin = fin.desembolsos
          .filter(d => d.estado === "Desembolsado")
          .reduce((s, d) => s + d.monto, 0);

        return (
          <div key={fin.id} className="bg-slate-900 border border-slate-800 rounded-3xl shadow-xl overflow-hidden">

            {/* Financiera Header */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 p-5 border-b border-slate-800">
              <div className="flex items-center gap-3 flex-1 min-w-0">
                <div className="p-2.5 rounded-2xl bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 shrink-0">
                  <Building2 className="w-5 h-5" />
                </div>
                <input
                  type="text"
                  value={fin.nombre}
                  onChange={e => handleUpdateFinanciera(fin.id, e.target.value)}
                  className="bg-transparent border-0 focus:outline-none text-base font-black text-white w-full truncate"
                  placeholder="Nombre de la financiera..."
                />
              </div>
              <div className="flex items-center gap-2 shrink-0">
                <div className="bg-slate-950 border border-slate-800 rounded-xl px-3 py-1.5 text-right">
                  <span className="block text-[10px] text-slate-400 font-bold">RECIBIDO / TOTAL</span>
                  <span className="font-mono text-xs font-bold text-emerald-400">
                    S/ {desembFin.toLocaleString("es-PE", { minimumFractionDigits: 2 })}
                  </span>
                  <span className="font-mono text-xs text-slate-500">
                    {" "}/ {totalFin.toLocaleString("es-PE", { minimumFractionDigits: 2 })}
                  </span>
                </div>
                <button
                  onClick={() => handleAddDesembolso(fin.id)}
                  className="flex items-center gap-1.5 bg-emerald-600/20 hover:bg-emerald-600/30 border border-emerald-500/30 text-emerald-400 font-bold text-xs px-3 py-1.5 rounded-xl transition"
                >
                  <Plus className="w-3.5 h-3.5" /> Desembolso
                </button>
                <button
                  onClick={() => handleToggleExpand(fin.id)}
                  className="p-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white transition"
                  title={fin.expandida ? "Contraer" : "Expandir"}
                >
                  {fin.expandida ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                </button>
                <button
                  onClick={() => handleDeleteFinanciera(fin.id)}
                  className="p-2 rounded-xl bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 transition"
                  title="Eliminar financiera"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </div>

            {/* Desembolsos Table */}
            {fin.expandida && (
              <div className="p-5 space-y-4">
                {fin.desembolsos.length === 0 && (
                  <p className="text-xs text-slate-500 text-center py-6">Sin desembolsos. Agrega uno con el botón de arriba.</p>
                )}

                {fin.desembolsos.map(des => {
                  const isSelectorThis =
                    selectorOpen?.finId === fin.id && selectorOpen?.desId === des.id;
                  const benNames = des.beneficiariosAsignados
                    .map(id => beneficiarios.find(b => b.id === id)?.postulante || id)
                    .join(", ");

                  return (
                    <div
                      key={des.id}
                      className="p-4 bg-slate-950 border border-slate-800 rounded-2xl space-y-3 hover:border-slate-700 transition"
                    >
                      {/* Row 1: Hito, Fecha, Monto, Estado, Acciones */}
                      <div className="grid grid-cols-1 sm:grid-cols-5 gap-3 items-end">
                        {/* Hito */}
                        <div className="sm:col-span-2 space-y-1">
                          <label className="text-[10px] font-bold text-slate-400 uppercase">Hito / Descripción</label>
                          <input
                            type="text"
                            value={des.hito}
                            onChange={e => handleUpdateDesembolso(fin.id, des.id, "hito", e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 focus:border-sky-500 rounded-xl px-3 py-2 text-xs text-white font-semibold focus:outline-none transition"
                          />
                        </div>
                        {/* Fecha */}
                        <div className="space-y-1">
                          <label className="text-[10px] font-bold text-slate-400 uppercase">Fecha</label>
                          <input
                            type="date"
                            value={des.fecha}
                            onChange={e => handleUpdateDesembolso(fin.id, des.id, "fecha", e.target.value)}
                            className="w-full bg-slate-900 border border-slate-800 focus:border-sky-500 rounded-xl px-3 py-2 text-xs text-slate-200 font-mono focus:outline-none transition"
                          />
                        </div>
                        {/* Monto */}
                        <div className="space-y-1">
                          <label className="text-[10px] font-bold text-slate-400 uppercase">Monto (S/)</label>
                          <div className="relative">
                            <DollarSign className="w-3.5 h-3.5 text-emerald-500 absolute left-2.5 top-1/2 -translate-y-1/2" />
                            <input
                              type="number"
                              step="500"
                              value={des.monto}
                              onChange={e => handleUpdateDesembolso(fin.id, des.id, "monto", parseFloat(e.target.value) || 0)}
                              className="w-full bg-slate-900 border border-slate-800 focus:border-emerald-500 rounded-xl pl-8 pr-3 py-2 text-xs text-emerald-400 font-mono font-bold focus:outline-none transition"
                            />
                          </div>
                        </div>
                        {/* Estado + acciones */}
                        <div className="flex items-end gap-2">
                          <div className="flex-1 space-y-1">
                            <label className="text-[10px] font-bold text-slate-400 uppercase">Estado</label>
                            <select
                              value={des.estado}
                              onChange={e => handleUpdateDesembolso(fin.id, des.id, "estado", e.target.value)}
                              className="w-full bg-slate-900 border border-slate-800 focus:border-sky-500 rounded-xl px-3 py-2 text-xs text-white font-bold focus:outline-none"
                            >
                              <option value="Pendiente">Pendiente</option>
                              <option value="En trámite">En trámite</option>
                              <option value="Desembolsado">Desembolsado</option>
                            </select>
                          </div>
                          <button
                            onClick={() => handleDeleteDesembolso(fin.id, des.id)}
                            className="p-2 rounded-xl bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 transition mb-0.5"
                            title="Eliminar desembolso"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </div>

                      {/* Row 2: Estado badge + Beneficiarios + Comprobante */}
                      <div className="flex flex-wrap items-center gap-3 pt-1 border-t border-slate-800">
                        <EstadoBadge estado={des.estado} />

                        {/* Beneficiarios Asignados */}
                        <div className="flex-1 min-w-0">
                          <button
                            onClick={() =>
                              setSelectorOpen(
                                isSelectorThis ? null : { finId: fin.id, desId: des.id }
                              )
                            }
                            className="flex items-center gap-1.5 text-xs font-bold text-slate-300 hover:text-white bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded-xl px-3 py-1.5 transition"
                          >
                            <Users className="w-3.5 h-3.5 text-sky-400" />
                            {des.beneficiariosAsignados.length === 0
                              ? "Asignar beneficiarios"
                              : `${des.beneficiariosAsignados.length} asignado(s)`}
                            {isSelectorThis ? (
                              <ChevronUp className="w-3.5 h-3.5 ml-1" />
                            ) : (
                              <ChevronDown className="w-3.5 h-3.5 ml-1" />
                            )}
                          </button>
                          {benNames && (
                            <p className="text-[10px] text-slate-500 mt-0.5 truncate max-w-xs">{benNames}</p>
                          )}
                        </div>

                        {/* Comprobante */}
                        <div className="flex items-center gap-2 shrink-0">
                          {des.comprobante ? (
                            <>
                              <button
                                onClick={() => setPreviewUrl(des.comprobante!)}
                                className="flex items-center gap-1.5 text-xs font-bold text-emerald-400 hover:text-emerald-300 bg-emerald-500/10 border border-emerald-500/20 rounded-xl px-3 py-1.5 transition"
                              >
                                <ImageIcon className="w-3.5 h-3.5" /> Ver comprobante
                              </button>
                              <button
                                onClick={() => handleUpdateDesembolso(fin.id, des.id, "comprobante", undefined)}
                                className="p-1.5 rounded-xl text-slate-400 hover:text-rose-400 hover:bg-rose-500/10 transition"
                                title="Eliminar comprobante"
                              >
                                <X className="w-3.5 h-3.5" />
                              </button>
                            </>
                          ) : (
                            <button
                              onClick={() => handleUploadClick(fin.id, des.id)}
                              className="flex items-center gap-1.5 text-xs font-bold text-slate-400 hover:text-white bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded-xl px-3 py-1.5 transition"
                            >
                              <Upload className="w-3.5 h-3.5" /> Subir comprobante
                            </button>
                          )}
                        </div>
                      </div>

                      {/* Beneficiary Checkbox Selector Dropdown */}
                      {isSelectorThis && (
                        <div className="mt-2 p-3 bg-slate-900 border border-slate-700 rounded-2xl space-y-1 max-h-48 overflow-y-auto">
                          <p className="text-[10px] font-bold text-slate-400 uppercase mb-2">
                            Selecciona beneficiarios para este desembolso:
                          </p>
                          {beneficiarios.length === 0 && (
                            <p className="text-xs text-slate-500">No hay beneficiarios registrados aún.</p>
                          )}
                          {beneficiarios.map(b => {
                            const checked = des.beneficiariosAsignados.includes(b.id);
                            return (
                              <label
                                key={b.id}
                                className={`flex items-center gap-2.5 p-2 rounded-xl cursor-pointer transition ${
                                  checked
                                    ? "bg-sky-600/10 border border-sky-500/30"
                                    : "hover:bg-slate-800 border border-transparent"
                                }`}
                              >
                                <input
                                  type="checkbox"
                                  checked={checked}
                                  onChange={() => toggleBeneficiario(fin.id, des.id, b.id)}
                                  className="accent-sky-500 w-3.5 h-3.5 rounded"
                                />
                                <div className="flex-1 min-w-0">
                                  <span className="block text-xs font-bold text-white truncate">
                                    {b.postulante}
                                  </span>
                                  <span className="block text-[10px] text-slate-400 font-mono">
                                    {b.id} · {b.distrito}, {b.departamento}
                                  </span>
                                </div>
                              </label>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { Beneficiario } from "../types";
import { getExpedienteStatusBadge } from "@/lib/status-helper";
import { FileText, Folder, Clipboard, UserPlus, CheckCircle2, Search, MapPin, Phone, Plus, ChevronRight } from "lucide-react";

interface DashboardProps {
  beneficiarios: Beneficiario[];
  onSelectExpediente: (id: string) => void;
  onNewExpediente: () => void;
}

export default function Dashboard({ beneficiarios, onSelectExpediente, onNewExpediente }: DashboardProps) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("TODOS");

  const filtered = beneficiarios.filter(b => {
    const matchesSearch = 
      b.postulante.toLowerCase().includes(search.toLowerCase()) ||
      b.dniPostulante.includes(search) ||
      b.id.toLowerCase().includes(search.toLowerCase()) ||
      (b.expediente && b.expediente.toLowerCase().includes(search.toLowerCase())) ||
      (b.distrito && b.distrito.toLowerCase().includes(search.toLowerCase()));

    const matchesStatus = statusFilter === "TODOS" || b.estado === statusFilter;
    return matchesSearch && matchesStatus;
  });

  // Uses the official 6-state system from status-helper

  return (
    <div className="w-full max-w-7xl mx-auto px-4 py-8 space-y-8 animate-in fade-in duration-300">

      {/* Dynamic Header & CTA */}
      <div className="relative overflow-hidden p-8 rounded-3xl bg-gradient-to-r from-slate-900 via-slate-900/90 to-indigo-950/60 border border-slate-800/80 shadow-2xl flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="absolute top-0 right-0 -mt-8 -mr-8 w-64 h-64 bg-indigo-600/10 rounded-full blur-3xl pointer-events-none"></div>

        <div className="space-y-2 relative z-10">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-xs font-bold tracking-wide uppercase">
            <span className="w-2 h-2 rounded-full bg-indigo-400 animate-pulse"></span> Sistema Techo Propio CSP
          </div>
          <h1 className="text-3xl sm:text-4xl font-black text-white tracking-tight">
            Expedientes de Beneficiarios
          </h1>
          <p className="text-slate-400 text-sm max-w-2xl">
            Gestión técnica integral automatizada para Construcción en Sitio Propio. Registro, presupuesto, planos de ingeniería y cronogramas.
          </p>
        </div>

        <button
          onClick={onNewExpediente}
          className="relative z-10 flex items-center justify-center gap-2.5 bg-sky-600 hover:bg-sky-500 active:bg-sky-700 text-white font-bold px-6 py-3.5 rounded-2xl transition-all duration-200 shadow-xl shadow-sky-600/25 hover:shadow-sky-500/40 hover:-translate-y-0.5"
        >
          <UserPlus className="w-5 h-5" />
          <span>Nuevo Registro</span>
        </button>
      </div>

      {/* Bento Grid Metrics */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: "Total Registros", val: beneficiarios.length, icon: Folder, col: "text-indigo-400", bg: "bg-indigo-500/10" },
          { label: "En Revisión / Inscritos", val: beneficiarios.filter(b => (b.estado || "").includes("Revisión") || (b.estado || "").includes("Inscrito")).length, icon: FileText, col: "text-sky-400", bg: "bg-sky-500/10" },
          { label: "Elegibles / Código Proyecto", val: beneficiarios.filter(b => (b.estado || "").includes("Elegible") || (b.estado || "").includes("Código")).length, icon: Clipboard, col: "text-emerald-400", bg: "bg-emerald-500/10" },
          { label: "Aprobados", val: beneficiarios.filter(b => (b.estado || "").includes("Aprobado")).length, icon: CheckCircle2, col: "text-purple-400", bg: "bg-purple-500/10" }
        ].map((stat, idx) => (
          <div key={idx} className="p-6 rounded-2xl bg-slate-900/60 border border-slate-800/80 hover:border-slate-700 transition duration-200 flex items-center justify-between shadow-lg">
            <div className="space-y-1">
              <span className="text-xs font-semibold text-slate-400 block tracking-wide">{stat.label}</span>
              <span className="text-3xl font-extrabold text-white block">{stat.val}</span>
            </div>
            <div className={`p-3.5 rounded-2xl border border-slate-800 ${stat.bg} ${stat.col}`}>
              <stat.icon className="w-6 h-6" />
            </div>
          </div>
        ))}
      </div>

      {/* Filters & Beneficiary List */}
      <div className="bg-slate-900/60 border border-slate-800/80 rounded-3xl overflow-hidden shadow-2xl">
        <div className="p-6 border-b border-slate-800/80 flex flex-col md:flex-row items-stretch md:items-center justify-between gap-4 bg-slate-900/80">
          <div className="flex items-center gap-3">
            <h2 className="text-lg font-extrabold text-white tracking-tight flex items-center gap-2">
              <Clipboard className="w-5 h-5 text-indigo-400" /> Registro de Expedientes
            </h2>
            <span className="text-xs font-bold text-slate-400 bg-slate-800 px-2.5 py-1 rounded-full border border-slate-700">
              {filtered.length} registrados
            </span>
          </div>

          <div className="flex flex-col sm:flex-row items-center gap-3">
            {/* Quick Status Filter Tabs */}
            <div className="flex items-center bg-slate-950 p-1 rounded-xl border border-slate-800 text-xs font-semibold w-full sm:w-auto overflow-x-auto gap-0.5">
              {[
                { label: "TODOS", val: "TODOS" },
                { label: "Revisión", val: "Expediente en Revisión" },
                { label: "Inscrito", val: "Expediente Inscrito" },
                { label: "Elegible", val: "Expediente Elegible" },
                { label: "No Elegible", val: "Expediente No Elegible" },
                { label: "Código Proy.", val: "Expediente con Código de Proyecto" },
                { label: "Aprobado", val: "Expediente Aprobado" },
              ].map(({ label, val }) => {
                const badge = val !== "TODOS" ? getExpedienteStatusBadge(val) : null;
                return (
                  <button
                    key={val}
                    onClick={() => setStatusFilter(val)}
                    className={`px-2.5 py-1.5 rounded-lg whitespace-nowrap transition ${
                      statusFilter === val
                        ? "bg-indigo-600 text-white shadow"
                        : "text-slate-400 hover:text-white"
                    }`}
                  >
                    {label}
                  </button>
                );
              })}
            </div>

            {/* Search Input */}
            <div className="relative w-full sm:w-64">
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
              <input
                type="text"
                placeholder="Buscar postulante, DNI..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full pl-10 pr-4 py-2 rounded-xl bg-slate-950 border border-slate-800 focus:border-indigo-500 focus:outline-none text-xs text-white placeholder-slate-500 transition"
              />
            </div>
          </div>
        </div>

        {/* List Content */}
        <div className="divide-y divide-slate-800/60">
          {filtered.length > 0 ? (
            filtered.map((b) => (
              <div 
                key={b.id} 
                onClick={() => onSelectExpediente(b.id)}
                className="p-5 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 cursor-pointer hover:bg-slate-800/40 transition duration-150 group"
              >
                <div className="space-y-2">
                  <div className="flex items-center gap-2.5 flex-wrap">
                    <span className="text-xs font-bold text-sky-400 bg-sky-500/10 border border-sky-500/20 px-2.5 py-0.5 rounded-lg font-mono">
                      {b.id}
                    </span>
                    {b.expediente && (
                      <span className="text-xs font-semibold text-slate-300 bg-slate-800 border border-slate-700 px-2.5 py-0.5 rounded-lg">
                        {b.expediente}
                      </span>
                    )}
                    {(() => {
                      const badge = getExpedienteStatusBadge(b.estado);
                      return (
                        <span className={`text-xs font-bold px-2.5 py-0.5 rounded-full border ${badge.colorClass}`}>
                          {badge.label}
                        </span>
                      );
                    })()}
                  </div>

                  <h3 className="text-base font-bold text-white group-hover:text-indigo-400 transition-colors">
                    {b.postulante}
                  </h3>

                  <div className="flex items-center gap-4 text-xs text-slate-400 flex-wrap">
                    <span className="flex items-center gap-1">
                      <MapPin className="w-3.5 h-3.5 text-slate-500" />
                      {b.direccion || "Dirección no asignada"} — <strong className="text-slate-300">{b.distrito}, {b.departamento}</strong>
                    </span>
                    {b.celular && (
                      <span className="flex items-center gap-1">
                        <Phone className="w-3.5 h-3.5 text-slate-500" />
                        {b.celular}
                      </span>
                    )}
                    <span className="font-mono text-slate-500">DNI: {b.dniPostulante || 'N/A'}</span>
                  </div>
                </div>

                <div className="flex items-center gap-2 self-end sm:self-center">
                  <span className="text-xs font-semibold text-slate-400 group-hover:text-white transition">
                    Abrir Expediente
                  </span>
                  <div className="p-2 rounded-xl bg-slate-800/80 group-hover:bg-indigo-600 transition duration-150">
                    <ChevronRight className="w-4 h-4 text-slate-300 group-hover:text-white group-hover:translate-x-0.5 transition" />
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div className="p-16 text-center text-slate-500 space-y-2">
              <Folder className="w-10 h-10 mx-auto text-slate-600" />
              <p className="text-sm font-semibold">No se encontraron expedientes con los criterios ingresados.</p>
              <button
                onClick={onNewExpediente}
                className="mt-2 inline-flex items-center gap-2 text-xs text-sky-400 hover:text-sky-300 font-bold"
              >
                <Plus className="w-3.5 h-3.5" /> Registrar nuevo postulante
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { Beneficiario, DocumentoAdjunto } from "../types";
import { 
  FileText, 
  Upload, 
  RefreshCw, 
  Eye, 
  Download, 
  Trash2, 
  Image as ImageIcon,
  ChevronDown,
  X,
  Plus,
  FolderOpen,
  UserCheck,
  ShieldAlert,
  FileCheck
} from "lucide-react";

interface DocumentManagerProps {
  beneficiarios: Beneficiario[];
  onRefresh?: () => void;
}

export const TIPOS_DOCUMENTOS = [
  "DNI Postulante",
  "DNI Cónyuge",
  "DNI Carga Familiar",
  "Copia Literal",
  "Autoavaluo",
  "Fotografías del Predio",
  "Otros Documentos"
];

export default function DocumentManager({ beneficiarios, onRefresh }: DocumentManagerProps) {
  const [selectedBeneficiaryId, setSelectedBeneficiaryId] = useState<string>(
    beneficiarios[0]?.id || ""
  );

  const [documentosLocal, setDocumentosLocal] = useState<{ [beneficiarioId: string]: DocumentoAdjunto[] }>({});
  const [tipoSeleccionado, setTipoSeleccionado] = useState<string>("DNI Postulante");
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewDoc, setPreviewDoc] = useState<DocumentoAdjunto | null>(null);

  const fileInputRef = React.useRef<HTMLInputElement>(null);

  const selectedBeneficiary = beneficiarios.find(b => b.id === selectedBeneficiaryId) || beneficiarios[0];

  // Merge beneficiary prop documents with local uploads
  const getDocsForBeneficiary = (bId: string): DocumentoAdjunto[] => {
    const b = beneficiarios.find(item => item.id === bId);
    const fromProp = b?.documentos || [];
    const fromLocal = documentosLocal[bId] || [];

    // Avoid duplicates by id
    const ids = new Set(fromProp.map(d => d.id));
    const merged = [...fromProp];
    for (const d of fromLocal) {
      if (!ids.has(d.id)) {
        merged.push(d);
      }
    }
    return merged;
  };

  const beneficiaryDocs = selectedBeneficiaryId ? getDocsForBeneficiary(selectedBeneficiaryId) : [];

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setSelectedFile(e.target.files[0]);
    }
  };

  const handleUploadSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedFile || !selectedBeneficiaryId) return;

    const fileName = selectedFile.name;
    const url = URL.createObjectURL(selectedFile);

    const newDoc: DocumentoAdjunto = {
      id: `DOC-${Date.now()}`,
      tipo: tipoSeleccionado,
      nombre: fileName,
      url,
      fecha: new Date().toLocaleDateString("es-PE")
    };

    setDocumentosLocal(prev => ({
      ...prev,
      [selectedBeneficiaryId]: [...(prev[selectedBeneficiaryId] || []), newDoc]
    }));

    // Send to server API endpoint as well
    fetch("/api/beneficiarios/documentos", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ beneficiarioId: selectedBeneficiaryId, documento: newDoc })
    }).then(() => {
      if (onRefresh) onRefresh();
    }).catch(console.error);

    setSelectedFile(null);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleDeleteDoc = async (docId: string) => {
    if (!selectedBeneficiaryId) return;

    setDocumentosLocal(prev => ({
      ...prev,
      [selectedBeneficiaryId]: (prev[selectedBeneficiaryId] || []).filter(d => d.id !== docId)
    }));

    try {
      await fetch(`/api/beneficiarios/documentos?beneficiarioId=${selectedBeneficiaryId}&docId=${docId}`, {
        method: "DELETE"
      });
      if (onRefresh) onRefresh();
    } catch (err) {
      console.error("Error eliminando documento:", err);
    }
  };

  return (
    <div className="w-full max-w-7xl mx-auto px-4 py-6 space-y-6 animate-in fade-in duration-300">

      {/* Top Header Banner */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-6 rounded-3xl bg-slate-900 border border-slate-800 shadow-xl">
        <div className="flex items-center gap-3">
          <div className="p-3 rounded-2xl bg-sky-500/10 text-sky-400 border border-sky-500/20">
            <FolderOpen className="w-6 h-6" />
          </div>
          <div>
            <h1 className="text-2xl font-black text-white tracking-tight">Gestor de Documentos y Archivos</h1>
            <p className="text-xs text-slate-400">
              Expedientes digitales con DNI, Copia Literal, Autoavaluo, fotos del predio y PDFs guardados desde la Web o Telegram.
            </p>
          </div>
        </div>

        {onRefresh && (
          <button
            onClick={onRefresh}
            className="flex items-center gap-2 border border-slate-700 hover:border-slate-500 bg-slate-800/80 hover:bg-slate-800 text-slate-200 hover:text-white text-xs font-bold px-4 py-2.5 rounded-xl transition duration-150 shadow"
          >
            <RefreshCw className="w-3.5 h-3.5 text-sky-400" /> Actualizar Base
          </button>
        )}
      </div>

      {/* Main Container */}
      <div className="bg-slate-900 border border-slate-800 rounded-3xl overflow-hidden shadow-2xl grid grid-cols-1 lg:grid-cols-12 min-h-[550px]">

        {/* Left Column: BENEFICIARY CARDS (4 Cols) */}
        <div className="lg:col-span-4 border-r border-slate-800/80 p-5 space-y-4 bg-slate-900/60 flex flex-col">
          <div className="flex items-center justify-between border-b border-slate-800/80 pb-3">
            <h2 className="text-xs font-black uppercase text-slate-300 tracking-wider flex items-center gap-2">
              <UserCheck className="w-4 h-4 text-sky-400" /> CUADROS DE BENEFICIARIOS
            </h2>
            <span className="text-xs font-bold text-sky-400 bg-sky-500/10 border border-sky-500/20 px-2.5 py-0.5 rounded-full font-mono">
              {beneficiarios.length}
            </span>
          </div>

          <div className="space-y-2 overflow-y-auto flex-1 max-h-[500px] pr-1">
            {beneficiarios.length === 0 ? (
              <div className="p-8 text-center text-slate-500 space-y-2 border border-dashed border-slate-800 rounded-2xl">
                <FileText className="w-8 h-8 mx-auto text-slate-600" />
                <p className="text-xs font-semibold">No hay beneficiarios registrados en el sistema.</p>
              </div>
            ) : (
              beneficiarios.map((b) => {
                const isSelected = selectedBeneficiaryId === b.id;
                const docsCount = getDocsForBeneficiary(b.id).length;

                return (
                  <div
                    key={b.id}
                    onClick={() => setSelectedBeneficiaryId(b.id)}
                    className={`p-4 rounded-2xl cursor-pointer transition-all duration-150 group border ${
                      isSelected 
                        ? "bg-slate-950 border-sky-500/50 text-white shadow-xl shadow-sky-500/10 ring-1 ring-sky-500/30" 
                        : "bg-slate-900/40 hover:bg-slate-800/50 border-slate-800/60 text-slate-400 hover:text-white"
                    }`}
                  >
                    <div className="flex items-start justify-between gap-2">
                      <div className="space-y-1 truncate">
                        <span className="text-[10px] font-bold font-mono px-2 py-0.5 rounded-md bg-slate-800 text-sky-400 border border-slate-700">
                          {b.id}
                        </span>
                        <h3 className={`text-xs font-black uppercase truncate transition-colors pt-1 ${isSelected ? "text-white" : "text-slate-200 group-hover:text-sky-400"}`}>
                          {b.postulante}
                        </h3>
                        <p className="text-[11px] font-medium text-slate-500 truncate">
                          DNI: {b.dniPostulante || "Sin DNI"} • {b.distrito || "S/D"}
                        </p>
                      </div>

                      <span className={`px-2.5 py-1 rounded-xl text-xs font-bold font-mono shrink-0 flex items-center gap-1 border ${
                        isSelected 
                          ? "bg-sky-600 text-white border-sky-500" 
                          : "bg-slate-800 text-slate-400 border-slate-700"
                      }`}>
                        <FileCheck className="w-3 h-3" /> {docsCount}
                      </span>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Right Column: DOCUMENT DETAILS & UPLOAD PANEL (8 Cols) */}
        <div className="lg:col-span-8 p-6 flex flex-col justify-between space-y-6 bg-slate-950/40">

          {/* Header for Selected Beneficiary */}
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800/80 pb-4">
            <div>
              <h2 className="text-lg font-black text-white tracking-tight uppercase">
                {selectedBeneficiary ? selectedBeneficiary.postulante : "SELECCIONA UN BENEFICIARIO"}
              </h2>
              <p className="text-xs text-slate-400 font-mono">
                Expediente: <span className="text-sky-400 font-bold">{selectedBeneficiary?.id || "-"}</span> | DNI: {selectedBeneficiary?.dniPostulante || "-"}
              </p>
            </div>

            <span className="text-xs font-bold text-sky-400 bg-sky-500/10 border border-sky-500/20 px-3.5 py-1 rounded-full font-mono self-start sm:self-auto">
              {beneficiaryDocs.length} {beneficiaryDocs.length === 1 ? "documento registrado" : "documentos registrados"}
            </span>
          </div>

          {/* Upload Toolbar Form */}
          {selectedBeneficiary && (
            <form onSubmit={handleUploadSubmit} className="p-4 rounded-2xl bg-slate-900 border border-slate-800 flex flex-col md:flex-row items-stretch md:items-end gap-3 shadow-lg">

              {/* Category Select */}
              <div className="space-y-1 md:w-5/12">
                <label className="text-[11px] font-bold uppercase tracking-wider text-slate-400">Tipo de Documento</label>
                <div className="relative">
                  <select
                    value={tipoSeleccionado}
                    onChange={(e) => setTipoSeleccionado(e.target.value)}
                    className="w-full bg-slate-950 border border-slate-800 focus:border-sky-500 rounded-xl px-3 py-2 text-xs text-white focus:outline-none appearance-none font-semibold transition"
                  >
                    {TIPOS_DOCUMENTOS.map(t => (
                      <option key={t} value={t}>{t}</option>
                    ))}
                  </select>
                  <ChevronDown className="w-4 h-4 text-slate-400 absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
                </div>
              </div>

              {/* File Picker */}
              <div className="space-y-1 md:w-5/12">
                <label className="text-[11px] font-bold uppercase tracking-wider text-slate-400">Archivo PDF o Imagen</label>
                <div className="flex items-center gap-2">
                  <input
                    type="file"
                    ref={fileInputRef}
                    onChange={handleFileChange}
                    accept=".pdf,.png,.jpg,.jpeg"
                    className="hidden"
                    id="doc-manager-file-input"
                  />
                  <label
                    htmlFor="doc-manager-file-input"
                    className="cursor-pointer bg-slate-800 hover:bg-slate-700 text-slate-200 font-bold text-xs px-3.5 py-2 rounded-xl border border-slate-700 transition shrink-0 flex items-center gap-1.5"
                  >
                    <Plus className="w-3.5 h-3.5 text-sky-400" /> Seleccionar
                  </label>
                  <span className="text-xs text-slate-400 truncate max-w-[150px] font-mono">
                    {selectedFile ? selectedFile.name : "Ningún archivo"}
                  </span>
                </div>
              </div>

              {/* Upload Submit Button */}
              <button
                type="submit"
                disabled={!selectedFile}
                className="flex items-center justify-center gap-2 bg-sky-600 hover:bg-sky-500 disabled:opacity-40 disabled:cursor-not-allowed text-white font-bold text-xs px-5 py-2.5 rounded-xl shadow-lg shadow-sky-600/20 transition shrink-0"
              >
                <Upload className="w-4 h-4" /> Subir
              </button>
            </form>
          )}

          {/* Documents Grid Display */}
          <div className="flex-1 overflow-y-auto max-h-[360px] pr-1">
            {beneficiaryDocs.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
                {beneficiaryDocs.map((doc) => {
                  const isImage = doc.nombre.toLowerCase().endsWith(".jpg") || 
                                  doc.nombre.toLowerCase().endsWith(".jpeg") || 
                                  doc.nombre.toLowerCase().endsWith(".png");

                  return (
                    <div 
                      key={doc.id} 
                      className="p-4 rounded-2xl bg-slate-900 border border-slate-800 hover:border-sky-500/40 transition duration-150 flex flex-col justify-between space-y-3 shadow-lg group"
                    >
                      <div className="space-y-2">
                        <div className="flex items-center justify-between">
                          <div className={`p-2.5 rounded-xl ${isImage ? "bg-indigo-500/10 text-indigo-400 border border-indigo-500/20" : "bg-sky-500/10 text-sky-400 border border-sky-500/20"}`}>
                            {isImage ? <ImageIcon className="w-5 h-5" /> : <FileText className="w-5 h-5" />}
                          </div>
                          <span className="text-[10px] font-bold text-slate-500 font-mono">
                            {doc.fecha || "Reciente"}
                          </span>
                        </div>

                        <div className="space-y-1">
                          <span className="inline-block text-[10px] font-bold uppercase tracking-wider text-sky-400 bg-sky-500/10 px-2 py-0.5 rounded-md border border-sky-500/20">
                            {doc.tipo}
                          </span>
                          <h3 className="text-xs font-mono text-slate-200 truncate pt-1" title={doc.nombre}>
                            {doc.nombre}
                          </h3>
                        </div>
                      </div>

                      {/* Action Buttons */}
                      <div className="flex items-center gap-1.5 pt-2 border-t border-slate-800/80">
                        <button
                          onClick={() => setPreviewDoc(doc)}
                          className="flex-1 flex items-center justify-center gap-1 bg-slate-950 hover:bg-slate-800 text-sky-400 hover:text-white text-[11px] font-bold py-1.5 rounded-xl border border-slate-800 transition"
                        >
                          <Eye className="w-3.5 h-3.5" /> Previsualizar
                        </button>
                        {doc.url ? (
                          <a
                            href={doc.url}
                            download={doc.nombre}
                            className="p-1.5 bg-slate-950 hover:bg-slate-800 text-slate-300 hover:text-white rounded-xl border border-slate-800 transition"
                            title="Descargar"
                          >
                            <Download className="w-3.5 h-3.5" />
                          </a>
                        ) : (
                          <button
                            onClick={() => alert(`Descargando copia local de: ${doc.nombre}`)}
                            className="p-1.5 bg-slate-950 hover:bg-slate-800 text-slate-300 hover:text-white rounded-xl border border-slate-800 transition"
                            title="Descargar"
                          >
                            <Download className="w-3.5 h-3.5" />
                          </button>
                        )}
                        <button
                          onClick={() => handleDeleteDoc(doc.id)}
                          className="p-1.5 bg-slate-950 hover:bg-rose-500/20 text-slate-500 hover:text-rose-400 rounded-xl border border-slate-800 transition"
                          title="Eliminar"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="py-16 text-center text-slate-500 space-y-2 border border-dashed border-slate-800 rounded-2xl bg-slate-900/30">
                <FileText className="w-8 h-8 mx-auto text-slate-600" />
                <p className="text-xs font-semibold">No hay documentos cargados aún para este beneficiario.</p>
                <p className="text-[11px] text-slate-600">Sube archivos usando el formulario arriba o envíalos desde Telegram.</p>
              </div>
            )}
          </div>

        </div>

      </div>

      {/* Modal Previewer */}
      {previewDoc && (
        <div className="fixed inset-0 z-50 bg-slate-950/80 backdrop-blur-md flex items-center justify-center p-4">
          <div className="bg-slate-900 border border-slate-800 rounded-3xl w-full max-w-3xl overflow-hidden shadow-2xl space-y-4 p-6 animate-in zoom-in-95 duration-150">
            <div className="flex items-center justify-between border-b border-slate-800 pb-3">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-xl bg-sky-500/10 text-sky-400 border border-sky-500/20">
                  <FileText className="w-5 h-5" />
                </div>
                <div>
                  <h3 className="text-sm font-black text-white">{previewDoc.tipo}</h3>
                  <p className="text-xs font-mono text-slate-400">{previewDoc.nombre}</p>
                </div>
              </div>

              <button
                onClick={() => setPreviewDoc(null)}
                className="p-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white transition"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            {/* Document Viewer Body */}
            <div className="w-full h-80 bg-slate-950 rounded-2xl border border-slate-800 flex flex-col items-center justify-center p-4 text-center overflow-hidden">
              {(() => {
                const url = previewDoc.url || `data:image/svg+xml;utf8,${encodeURIComponent(`
                  <svg xmlns="http://www.w3.org/2000/svg" width="600" height="400" viewBox="0 0 600 400">
                    <rect width="600" height="400" fill="#0f172a" rx="20"/>
