    e.preventDefault();
    setIsLoading(true);
    setError("");

    // Simulate network delay for premium feel
    setTimeout(() => {
      if (isRegistering) {
        // Simulate registration (in a real DB we would create the user here)
        if (!email || !username || !password) {
          setError("Por favor completa todos los campos.");
        } else {
          onLogin(); // auto login after register
        }
        setIsLoading(false);
      } else {
        // Simulate login
        if (username === "admin" && password === "admin123") {
          onLogin();
