"use client";

import React, { useState, useEffect, useCallback } from "react";
import confetti from "canvas-confetti";
import { Beneficiario, Dimensiones, Insumo, PartidaAPU } from "./types";
import { BENEFICIARIOS_INICIALES, INSUMOS_INICIALES, PARTIDAS_APU_INICIALES } from "./constants/initialData";
import { ArrowLeft, User, Ruler, Wrench, FileSpreadsheet, Hourglass, FileText, CheckCircle2, UserPlus, Send } from "lucide-react";

import Sidebar, { NavView } from "./components/Sidebar";
import PeruMap from "./components/PeruMap";
import Dashboard from "./components/Dashboard";
import BeneficiaryFicha from "./components/BeneficiaryFicha";
import DocumentManager from "./components/DocumentManager";
import ExpedientesView from "./components/ExpedientesView";
import FullRegistrationForm from "./components/FullRegistrationForm";
import InteractivePlano from "./components/InteractivePlano";
import MetradosSheet from "./components/MetradosSheet";
import ApuLibrary from "./components/ApuLibrary";
import PresupuestoSheet from "./components/PresupuestoSheet";
import CronogramaObra from "./components/CronogramaObra";
import PlanosIngenieria from "./components/PlanosIngenieria";
import CronogramaPagos from "./components/CronogramaPagos";
import CronogramaMaestros from "./components/CronogramaMaestros";
import LoginScreen from "./components/LoginScreen";

export default function Home() {
  const [isLoggedIn, setIsLoggedIn] = useState<boolean>(false);
  const [beneficiarios, setBeneficiarios] = useState<Beneficiario[]>(BENEFICIARIOS_INICIALES);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [editingBeneficiaryForForm, setEditingBeneficiaryForForm] = useState<Beneficiario | null>(null);
  const [activeTab, setActiveTab] = useState<string>("ficha");
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);

  // Navigation View State
  const [activeNavView, setActiveNavView] = useState<NavView>("resumen");
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState<boolean>(false);

  // Dynamic engineering simulation states
  const [dimensiones, setDimensiones] = useState<Dimensiones>({ largo: 6.5, ancho: 5.5, altura: 2.80, espesorMuro: 0.15, habitaciones: 2 });
  const [insumos, setInsumos] = useState<Insumo[]>(INSUMOS_INICIALES);
  const [partidasApu, setPartidasApu] = useState<PartidaAPU[]>(PARTIDAS_APU_INICIALES);

  const selectedBeneficiary = beneficiarios.find(b => b.id === selectedId);

  const handleSelectExpediente = (id: string) => {
    setSelectedId(id);
    setActiveTab("ficha");
    setActiveNavView("expedientes");
    setDimensiones({ largo: 6.5, ancho: 5.5, altura: 2.80, espesorMuro: 0.15, habitaciones: 2 });
  };

  const handleOpenNewModal = () => {
    setIsModalOpen(true);
  };

  const loadBeneficiarios = useCallback(async () => {
    try {
      const res = await fetch("/api/beneficiarios");
      if (res.ok) {
        const data = await res.json();
        if (Array.isArray(data) && data.length > 0) {
          setBeneficiarios(data);
        }
      }
    } catch (err) {
      console.error("Error cargando beneficiarios desde API:", err);
    }
  }, []);

  useEffect(() => {
    loadBeneficiarios();
  }, [loadBeneficiarios]);

  const handleSaveBeneficiary = async (updated: Beneficiario) => {
    const exists = beneficiarios.some(b => b.id === updated.id);
    if (exists) {
      setBeneficiarios(prev => prev.map(b => b.id === updated.id ? updated : b));
      fetch("/api/beneficiarios", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updated),
      }).catch(console.error);
    } else {
      setBeneficiarios(prev => [updated, ...prev]);
      setSelectedId(updated.id);
      setActiveTab("ficha");
      setActiveNavView("expedientes");
      fetch("/api/beneficiarios", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updated),
      }).catch(console.error);
    }
    confetti({ particleCount: 120, spread: 80, origin: { y: 0.6 } });
  };

  const handleDeleteBeneficiary = async (id: string) => {
    setBeneficiarios(prev => prev.filter(b => b.id !== id));
    if (selectedId === id) setSelectedId(null);
    fetch(`/api/beneficiarios?id=${id}`, { method: "DELETE" }).catch(console.error);
  };

  const handleEditBeneficiary = async (updated: Beneficiario) => {
    setBeneficiarios(prev => prev.map(b => b.id === updated.id ? updated : b));
    fetch("/api/beneficiarios", {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(updated),
    }).catch(console.error);
  };

  const handleUpdateInsumoPrice = (id: string, newPrice: number) => {
    setInsumos(prev => prev.map(ins => ins.id === id ? { ...ins, precioUnitario: newPrice } : ins));
  };

  const calculateTotalBudget = (): number => {
    const area = dimensiones.largo * dimensiones.ancho;
    const longMuros = (2 * (dimensiones.largo + dimensiones.ancho)) + (dimensiones.habitaciones >= 1 ? dimensiones.ancho : 0) + (dimensiones.habitaciones >= 2 ? (dimensiones.largo * 0.5) : 0);
    const getQty = (item: string) => {
      if (["01.01", "01.02", "06.01"].includes(item)) return area;
      if (item === "02.01") return longMuros * 0.4 * 1;
      if (item === "03.01") return longMuros * 0.4 * 0.8;
      if (item === "04.01") return Math.max(0, (longMuros * dimensiones.altura) - 6.5);
      if (item === "05.01") return 12 * 0.15 * 0.25 * dimensiones.altura;
      if (item === "07.01" || item === "07.02") return Math.max(0, (longMuros * dimensiones.altura) - 6.5) * 2;
      return 1;
    };
    let totalDirecto = 0;
    partidasApu.forEach(p => {
      let unitCost = 0;
      [...p.manoDeObra, ...p.materiales, ...p.equipos].forEach(d => {
        const ins = insumos.find(i => i.id === d.insumoId);
        if (ins) unitCost += d.coeficiente * ins.precioUnitario;
      });
      totalDirecto += getQty(p.item) * unitCost;
    });
    return (totalDirecto * 1.15) * 1.18;
  };

  const nextAutoId = `REG-${String(beneficiarios.length + 1).padStart(4, "0")}`;

  if (!isLoggedIn) {
    return <LoginScreen onLogin={() => setIsLoggedIn(true)} />;
  }

  return (
    <div className="flex h-screen w-full bg-slate-950 text-slate-100 font-sans selection:bg-indigo-500 selection:text-white overflow-hidden">

      {/* Left Sidebar Menu (Maza Quiroz) */}
      <Sidebar
        activeView={activeNavView}
        onSelectView={(view) => {
          setActiveNavView(view);
          if (view === "expedientes" && !selectedId && beneficiarios.length > 0) {
            setSelectedId(beneficiarios[0].id);
          }
        }}
        isCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
        onLogout={() => setIsLoggedIn(false)}
      />

      {/* Main App Content Area */}
      <div className="flex-1 flex flex-col h-full overflow-y-auto bg-slate-950">

        {/* Top App Header */}
        <header className="sticky top-0 z-20 border-b border-slate-800/80 bg-slate-950/80 backdrop-blur-xl px-6 py-4 flex items-center justify-between shadow-md">
          <div className="flex items-center gap-3">
            <h1 className="text-base font-extrabold tracking-tight text-white flex items-center gap-2">
              Techo Propio <span className="text-xs px-2.5 py-0.5 rounded-full bg-sky-500/10 text-sky-400 font-bold border border-sky-500/20">Maza Quiroz</span>
            </h1>
          </div>

          <div className="flex items-center gap-3">
            <span className="text-xs text-slate-400 font-semibold border border-slate-800 bg-slate-900 px-3 py-1.5 rounded-xl">
              Sistema de Gestión Techo Propio
            </span>
          </div>
        </header>

        {/* View Router */}
        <main className="flex-1 p-4 md:p-6 space-y-6">

          {/* Module 1: Resumen (Mapa Interactivo del Perú) */}
          {activeNavView === "resumen" && (
            <PeruMap
              beneficiarios={beneficiarios}
              onSelectDepartmentFilter={() => {
                setActiveNavView("registros");
              }}
              onRefresh={() => {
                loadBeneficiarios();
                confetti({ particleCount: 50, spread: 60 });
              }}
            />
          )}

          {/* Module 2: Registros (Lista de Beneficiarios + Filtros UBIGEO + Excel) */}
          {activeNavView === "registros" && (
            <ExpedientesView
              beneficiarios={beneficiarios}
              onSelectBeneficiary={(id) => {
                setSelectedId(id);
                setActiveNavView("expedientes");
              }}
              onDeleteBeneficiary={handleDeleteBeneficiary}
              onEditBeneficiary={handleEditBeneficiary}
              onOpenEditForm={(b) => {
                setEditingBeneficiaryForForm(b);
                setActiveNavView("ficha_registro");
              }}
              onRefresh={() => {
                loadBeneficiarios();
                confetti({ particleCount: 50, spread: 60 });
              }}
            />
          )}

          {/* Module 3: Ficha de Registro (Formulario Oficial Completo) */}
          {activeNavView === "ficha_registro" && (
            <FullRegistrationForm
              onSave={(updated) => {
                handleSaveBeneficiary(updated);
                setEditingBeneficiaryForForm(null);
                setActiveNavView("registros");
              }}
              nextId={nextAutoId}
              editingData={editingBeneficiaryForForm}
              onCancelEdit={() => {
                setEditingBeneficiaryForForm(null);
                setActiveNavView("registros");
              }}
            />
          )}

          {/* Module 4: Expediente Técnico e Ingeniería (Imagen 1: Ficha, Plano, Metrados, APU, Presupuesto, Cronograma, DWG) */}
          {activeNavView === "expedientes" && (
            !selectedId ? (
              <div className="w-full max-w-7xl mx-auto p-8 rounded-3xl bg-slate-900 border border-slate-800 text-center space-y-4 shadow-2xl">
                <Wrench className="w-12 h-12 mx-auto text-sky-400" />
                <h2 className="text-xl font-black text-white">Selecciona un Beneficiario para el Expediente Técnico</h2>
                <p className="text-xs text-slate-400 max-w-md mx-auto">
                  Por favor selecciona un expediente de la lista en el menú Registros para visualizar la Ficha Familiar, Planos, Metrados, APU y Presupuesto de obra.
                </p>
                <div className="pt-2">
                  <button
                    onClick={() => {
                      if (beneficiarios.length > 0) setSelectedId(beneficiarios[0].id);
                      else setActiveNavView("registros");
                    }}
                    className="bg-sky-600 hover:bg-sky-500 text-white font-bold text-xs px-5 py-2.5 rounded-xl transition shadow-lg shadow-sky-600/20"
                  >
                    Ver Expediente de {beneficiarios[0]?.postulante || "Ejemplo"}
                  </button>
                </div>
              </div>
            ) : (
              <div className="w-full max-w-7xl mx-auto space-y-6 animate-in fade-in duration-200">

                {/* Header for Selected Beneficiary */}
                <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 p-6 rounded-3xl bg-slate-900/80 border border-slate-800 border-l-4 border-l-sky-500 shadow-xl">
                  <div className="space-y-1">
                    <button 
                      onClick={() => {
                        setActiveNavView("registros");
                      }} 
                      className="inline-flex items-center gap-1.5 text-xs text-sky-400 font-bold hover:text-sky-300 transition-colors"
                    >
                      <ArrowLeft className="w-3.5 h-3.5" /> Volver a Lista de Beneficiarios
                    </button>
                    <h2 className="text-2xl font-black text-white">{selectedBeneficiary?.postulante}</h2>
                    <p className="text-xs text-slate-400">
                      Expediente: <span className="font-bold font-mono text-sky-400">{selectedBeneficiary?.id}</span> — {selectedBeneficiary?.distrito}, {selectedBeneficiary?.departamento}
                    </p>
                  </div>

                </div>


                {/* Navigation Tabs */}
                <div className="flex gap-2 overflow-x-auto pb-2 border-b border-slate-800/80 no-print">
                  {[
                    { id: "ficha", label: "Ficha Familiar", icon: User },
                    { id: "plano", label: "Plano Interactivo", icon: Ruler },
                    { id: "presupuesto", label: "Presupuesto", icon: FileText },
                    { id: "gantt", label: "Cronograma de Obra", icon: Hourglass },
                    { id: "planos", label: "DWG e Ingeniería", icon: CheckCircle2 }
                  ].map(tab => (
                    <button
                      key={tab.id}
                      onClick={() => setActiveTab(tab.id)}
                      className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-bold whitespace-nowrap transition duration-150 ${activeTab === tab.id ? "bg-sky-600 text-white shadow-lg shadow-sky-600/20" : "text-slate-400 hover:text-white hover:bg-slate-800/50"}`}
                    >
                      <tab.icon className="w-4 h-4" /> {tab.label}
                    </button>
                  ))}
                </div>

                {/* Tab Views */}
                <div className="py-2">
                  {activeTab === "ficha" && selectedBeneficiary && (
                    <BeneficiaryFicha
                      beneficiario={selectedBeneficiary}
                      onSave={handleSaveBeneficiary}
                      onBack={() => setActiveNavView("registros")}
                    />
                  )}
                  {activeTab === "plano" && (
                    <InteractivePlano
                      dimensiones={dimensiones}
                      onChange={setDimensiones}
                    />
                  )}
                  {activeTab === "presupuesto" && (
                    <PresupuestoSheet
                      dimensiones={dimensiones}
                      insumos={insumos}
                      partidasApu={partidasApu}
                    />
                  )}
                  {activeTab === "gantt" && (
                    <CronogramaObra />
                  )}
                  {activeTab === "planos" && (
                    <PlanosIngenieria />
                  )}
                </div>
              </div>
            )
          )}

          {/* Module 5: Documentos (Gestor de Documentos) */}
          {activeNavView === "documentos" && (
            <DocumentManager beneficiarios={beneficiarios} onRefresh={loadBeneficiarios} />
          )}

          {/* Module 6: Cronograma de Pagos (Financieras + Desembolsos) */}
          {activeNavView === "pagos" && (
            <CronogramaPagos beneficiarios={beneficiarios} />
          )}

          {/* Module 7: Maestros de Obra */}
          {activeNavView === "maestros" && (
            <CronogramaMaestros beneficiarios={beneficiarios} />
          )}

        </main>
      </div>
    </div>
  );
}

import fs from "fs";
import path from "path";
import { Beneficiario, MaestroObra, DocumentoAdjunto } from "../app/types";
import { BENEFICIARIOS_INICIALES } from "../app/constants/initialData";

const DB_PATH = path.join(process.cwd(), "data", "db.json");

export interface DatabaseSchema {
  beneficiarios: Beneficiario[];
  maestros: MaestroObra[];
}

function ensureDirectoryExistence(filePath: string) {
  const dirname = path.dirname(filePath);
  if (fs.existsSync(dirname)) {
    return true;
  }
  ensureDirectoryExistence(dirname);
  fs.mkdirSync(dirname);
}

export function getDb(): DatabaseSchema {
  try {
    if (!fs.existsSync(DB_PATH)) {
      ensureDirectoryExistence(DB_PATH);
      const initialDb: DatabaseSchema = {
        beneficiarios: BENEFICIARIOS_INICIALES,
        maestros: []
      };
      fs.writeFileSync(DB_PATH, JSON.stringify(initialDb, null, 2), "utf-8");
      return initialDb;
    }
    const raw = fs.readFileSync(DB_PATH, "utf-8");
    const parsed = JSON.parse(raw) as DatabaseSchema;
    if (!parsed.maestros) parsed.maestros = [];
    return parsed;
  } catch (err) {
    console.error("Error reading db.json, returning fallback", err);
    return { beneficiarios: BENEFICIARIOS_INICIALES, maestros: [] };
  }
}

export function saveDb(data: DatabaseSchema): void {
  try {
    ensureDirectoryExistence(DB_PATH);
    fs.writeFileSync(DB_PATH, JSON.stringify(data, null, 2), "utf-8");
  } catch (err) {
    console.error("Error saving to db.json", err);
  }
}

export function getBeneficiarios(): Beneficiario[] {
  return getDb().beneficiarios;
}

export function addBeneficiario(b: Beneficiario): Beneficiario {
  const db = getDb();
  db.beneficiarios.unshift(b);
  saveDb(db);
  return b;
}

export function updateBeneficiario(b: Beneficiario): Beneficiario {
  const db = getDb();
  db.beneficiarios = db.beneficiarios.map(item => (item.id === b.id ? b : item));
  saveDb(db);
  return b;
}

export function deleteBeneficiario(id: string): void {
  const db = getDb();
  db.beneficiarios = db.beneficiarios.filter(item => item.id !== id);
  saveDb(db);
}

export function addDocumentoToBeneficiario(beneficiarioId: string, doc: DocumentoAdjunto): Beneficiario | null {
  const db = getDb();
  const b = db.beneficiarios.find(item => item.id === beneficiarioId);
  if (!b) return null;
  if (!b.documentos) b.documentos = [];
  b.documentos.push(doc);
  saveDb(db);
  return b;
}

export function deleteDocumentoFromBeneficiario(beneficiarioId: string, docId: string): Beneficiario | null {
  const db = getDb();
  const b = db.beneficiarios.find(item => item.id === beneficiarioId);
  if (!b) return null;
  if (b.documentos) {
    b.documentos = b.documentos.filter(d => d.id !== docId);
  }
  saveDb(db);
  return b;
}

export function getMaestros(): MaestroObra[] {
  return getDb().maestros || [];
}

export function addMaestro(m: MaestroObra): MaestroObra {
  const db = getDb();
  if (!db.maestros) db.maestros = [];
  db.maestros.unshift(m);

  // If assigned to beneficiary, link them
  if (m.beneficiarioAsignadoId) {
    const b = db.beneficiarios.find(item => item.id === m.beneficiarioAsignadoId);
    if (b) {
      b.maestroAsignadoId = m.id;
      b.maestroAsignadoNombre = m.nombre;
    }
  }

  saveDb(db);
  return m;
}

export function updateBeneficiarioEtapa(id: string, etapa: string, pct: number): Beneficiario | null {
  const db = getDb();
  const b = db.beneficiarios.find(item => item.id === id);
  if (!b) return null;
  b.etapaVivienda = etapa;
  b.avanceViviendaPct = pct;
  saveDb(db);
  return b;
}

export function updateBeneficiarioEstado(id: string, nuevoEstado: string): Beneficiario | null {
  const db = getDb();
  const b = db.beneficiarios.find(item => item.id === id);
  if (!b) return null;
  b.estado = nuevoEstado as any;
  saveDb(db);
  return b;
}

export function assignMaestroToBeneficiarios(maestroId: string, maestroNombre: string, beneficiarioIds: string[]): number {
  const db = getDb();
  let updatedCount = 0;
  db.beneficiarios = db.beneficiarios.map(b => {
    if (beneficiarioIds.includes(b.id)) {
      updatedCount++;
      return {
        ...b,
        maestroAsignadoId: maestroId,
        maestroAsignadoNombre: maestroNombre
      };
    }
    return b;
  });
  saveDb(db);
  return updatedCount;
}

import { Beneficiario, MaestroObra, DocumentoAdjunto } from "../app/types";
import { 
  getBeneficiarios, 
  addBeneficiario, 
  updateBeneficiario, 
  deleteBeneficiario,
  getMaestros,
  addMaestro,
  addDocumentoToBeneficiario,
  updateBeneficiarioEtapa,
  updateBeneficiarioEstado,
  assignMaestroToBeneficiarios
} from "./db";
import { getSession, setSession, clearSession } from "./session-store";

// Common Spanish stop words and query prefixes to filter out when searching for names
const STOP_WORDS = new Set([
  "necesito", "dame", "dame el", "dame la", "su", "el", "la", "los", "las", "un", "una",
  "de", "del", "en", "que", "cual", "es", "esta", "donde", "vive", "como", "va", "quien",
  "construye", "telefono", "celular", "correo", "email", "direccion", "ubicacion",
  "departamento", "provincia", "distrito", "estado", "etapa", "casa", "vivienda",
  "ficha", "ver", "mostrar", "beneficiario", "cliente", "expediente", "datos",
  "informacion", "maestro", "contrato", "dni", "por", "favor", "hola", "bot", "asistente",
  "cuanto", "cuantos", "cuantas", "etapa", "avance", "pagos", "desembolso", "desembolsos",
  "coordenadas", "coordenada", "cordenadas", "cordenada", "x", "y"
]);

export function normalizeText(text: string): string {
  return text
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^\w\s]/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function extractDni(text: string): string | null {
  const match = text.match(/\b\d{8}\b/);
  return match ? match[0] : null;
}

export function findBeneficiary(query: string): Beneficiario | null {
  const list = getBeneficiarios();
  if (!query || list.length === 0) return null;

  // 1. Direct DNI match
  const dni = extractDni(query);
  if (dni) {
    const byDni = list.find(b => b.dniPostulante === dni);
    if (byDni) return byDni;
  }

  // 2. Exact ID match
  const cleanQuery = query.trim().toLowerCase();
  const byId = list.find(b => b.id.toLowerCase() === cleanQuery);
  if (byId) return byId;

  const qNorm = normalizeText(query);

  // 3. Exact full name match in normalized text
  for (const b of list) {
    const bNameNorm = normalizeText(b.postulante);
    if (qNorm.includes(bNameNorm) || bNameNorm.includes(qNorm)) {
      return b;
    }
  }

  // 4. Token matching without stop words
  const tokens = qNorm.split(" ").filter(w => w.length > 2 && !STOP_WORDS.has(w));
  if (tokens.length > 0) {
    let bestMatch: Beneficiario | null = null;
    let maxScore = 0;

    for (const b of list) {
      const bNameNorm = normalizeText(b.postulante);
      let score = 0;
      for (const t of tokens) {
        if (bNameNorm.includes(t)) {
          score += t.length;
        }
      }

      if (score > maxScore) {
        maxScore = score;
        bestMatch = b;
      }
    }

    if (bestMatch && maxScore >= 3) {
      return bestMatch;
    }
  }

  return null;
}

