export async function processUserMessage(chatId: number | string, text: string, fileUrl?: string): Promise<string> {
  const norm = normalizeText(text);
  const currentSession = getSession(chatId);

  // ─── 0. EXIT / CANCEL SESSION OR RESTART REGISTRATION ─────────────────────
  if (
    norm === "nada" ||
    norm === "cancelar" ||
    norm === "cancelar edicion" ||
    norm === "terminar" ||
    norm === "terminar edicion" ||
    norm === "listo" ||
    norm === "fin" ||
    norm === "salir"
  ) {
    if (currentSession.type !== "IDLE") {
      clearSession(chatId);
      return "Proceso cancelado / finalizado.";
    }
  }

  // ─── 0.1 NEW REGISTRATION INTENT (EXPLICIT TRIGGER AT ANY TIME) ───────────
  const isRegisterIntent = 
    norm.includes("nuevo registro") ||
    norm.includes("registrar nuevo") ||
    norm.includes("registrar beneficiario") ||
    norm.includes("registrar un beneficiario") ||
    norm.includes("registrar un nuevo beneficiario") ||
    norm.includes("agregar beneficiario") ||
    norm.includes("crear beneficiario") ||
    norm.includes("nuevo beneficiario") ||
    norm.includes("ingresar beneficiario") ||
    norm.includes("registrar familia") ||
    norm.includes("crear expediente") ||
    norm.includes("nuevo expediente") ||
    norm.includes("registrar cliente") ||
    norm.includes("registrar un cliente") ||
    norm.includes("registrar un nuevo cliente") ||
    norm.includes("nuevo cliente") ||
    norm.includes("iniciar registro") ||
    norm.includes("quiero registrar") ||
    norm.includes("alta beneficiario") ||
    norm.includes("alta de beneficiario") ||
    norm.includes("alta cliente") ||
    norm.includes("inscripcion") ||
    norm.includes("inscribir") ||
    norm.includes("postular") ||
    norm === "registrar" ||
    norm === "registro" ||
    norm === "nuevo";

  if (isRegisterIntent) {
    setSession(chatId, { type: "REGISTERING", step: 0, draft: {} });
    return `
Vamos a registrar un nuevo beneficiario.

👉 ${REGISTER_STEPS[0].prompt}
`.trim();
  }

  // ─── 0.2 NEW MAESTRO DE OBRA REGISTRATION INTENT ────────────────────────
  const isMaestroRegisterIntent = 
    norm.includes("registrar maestro") ||
    norm.includes("nuevo maestro") ||
    norm.includes("crear maestro") ||
    norm.includes("ingresar maestro") ||
    norm.includes("maestro de obra") ||
    norm.includes("agregar maestro");

  if (isMaestroRegisterIntent) {
    setSession(chatId, { type: "REGISTERING_MAESTRO", step: 0, draft: {} });
    return `
Vamos a registrar un nuevo Maestro de Obra.

👉 ${MAESTRO_STEPS[0].prompt}
`.trim();
  }

  // ─── 1. ACTIVE REGISTRATION WIZARD SESSION ────────────────────────────────
  if (currentSession.type === "REGISTERING") {
    const stepIndex = currentSession.step;
    const currentStepConfig = REGISTER_STEPS[stepIndex];
    const val = text.trim();

    // Handle boolean for tieneConyuge
    let isHasConyuge = true;
    if (currentStepConfig.key === "tieneConyuge") {
      isHasConyuge = norm.includes("si") || norm === "s";
    }

    const draft = {
      ...currentSession.draft,
      [currentStepConfig.key]: currentStepConfig.key === "tieneConyuge" ? isHasConyuge : val,
    };

    let nextStepIndex = stepIndex + 1;

    // IF USER ANSWERS "NO" TO CÓNYUGE -> SKIP ALL CÓNYUGE QUESTIONS (JUMP DIRECTLY TO AREA TOTAL)
    if (currentStepConfig.key === "tieneConyuge" && !isHasConyuge) {
      const areaTotalIndex = REGISTER_STEPS.findIndex(s => s.key === "areaTotal");
      if (areaTotalIndex !== -1) {
        nextStepIndex = areaTotalIndex;
      }
    }

    if (nextStepIndex < REGISTER_STEPS.length) {
      setSession(chatId, { type: "REGISTERING", step: nextStepIndex, draft });
      const nextConfig = REGISTER_STEPS[nextStepIndex];
      return `${nextConfig.prompt}`;
    } else {
      // Registration completed!
      const count = getBeneficiarios().length + 1;
      const id = `REG-${String(count).padStart(4, "0")}`;

      const dep = (draft.departamento || "SAN MARTIN").toUpperCase();
      const prov = (draft.provincia || "SAN MARTIN").toUpperCase();
      const dist = (draft.distrito || "TARAPOTO").toUpperCase();

      const rawPostulante = (draft.postulante || "").trim();
      let apPaterno = (draft.apellidoPaterno || "").trim();
      let apMaterno = (draft.apellidoMaterno || "").trim();
      let nomPost = (draft.nombres || "").trim();

      if (rawPostulante && (!apPaterno || !nomPost)) {
        const parts = rawPostulante.split(/\s+/).filter(Boolean);
        if (parts.length === 1) {
          nomPost = parts[0];
        } else if (parts.length === 2) {
          nomPost = parts[0];
          apPaterno = parts[1];
        } else if (parts.length === 3) {
          nomPost = parts[0];
          apPaterno = parts[1];
          apMaterno = parts[2];
        } else if (parts.length >= 4) {
          nomPost = parts.slice(0, parts.length - 2).join(" ");
          apPaterno = parts[parts.length - 2];
          apMaterno = parts[parts.length - 1];
        }
      }

      const fullPostulanteName = `${nomPost} ${apPaterno} ${apMaterno}`.trim() || rawPostulante || "Postulante Sin Nombre";

      const conyugeNombreFull = draft.tieneConyuge
        ? (draft.conyuge || `${draft.nombresConyuge || ""} ${draft.apellidoPaternoConyuge || ""} ${draft.apellidoMaternoConyuge || ""}`.trim())
        : "";

      const newBeneficiario: Beneficiario = {
        id,
        expediente: dep,
        departamento: dep,
        provincia: prov,
        distrito: dist,
        centroPoblado: draft.centroPoblado !== "Ninguno" ? draft.centroPoblado : "",
        barrioSector: draft.barrioSector !== "Ninguno" ? draft.barrioSector : "",
        calle: draft.calle,
        manzana: draft.manzana,
        lote: draft.lote,
        coordenadaX: draft.coordenadaX,
        coordenadaY: draft.coordenadaY,
        partidaElectronica: draft.partidaElectronica !== "Ninguna" ? draft.partidaElectronica : "",
        codigoCatastral: `${Math.floor(10000000000000 + Math.random() * 90000000000000)}`,
        postulante: fullPostulanteName,
        apellidoPaterno: apPaterno,
        apellidoMaterno: apMaterno,
        nombres: nomPost,
        dniPostulante: draft.dniPostulante || "00000000",
        fechaNacimiento: draft.fechaNacimiento,
        sexo: draft.sexo,
        celular: draft.celular || "Sin celular",
        correo: draft.correo !== "Ninguno" ? draft.correo : "",
        estadoCivil: draft.estadoCivil || "Soltero/a",
        tieneConyuge: Boolean(draft.tieneConyuge),
        conyuge: conyugeNombreFull,
        dniConyuge: draft.tieneConyuge ? draft.dniConyuge : "",
        apellidoPaternoConyuge: draft.apellidoPaternoConyuge,
        apellidoMaternoConyuge: draft.apellidoMaternoConyuge,
        nombresConyuge: draft.nombresConyuge,
        fechaNacimientoConyuge: draft.tieneConyuge ? draft.fechaNacimientoConyuge : "",
        direccion: `${draft.calle || ""} Mz ${draft.manzana || ""} Lt ${draft.lote || ""}`.trim() || `Distrito de ${dist}`,
        areaTotal: draft.areaTotal || "45.00",
        porFrente: draft.porFrente || "6.50",
        porDerecha: draft.porDerecha || "7.00",
        porIzquierda: draft.porIzquierda || "7.00",
        porFondo: draft.porFondo || "6.50",
        areaTechada: draft.areaTechada || "35.75",
        areaConstruida: draft.areaConstruida || "35.75",
        programa: draft.programa || "CSP",
        estado: (draft.estado as any) || "Activo",
        notas: draft.notas !== "Ninguna" ? draft.notas : "",
        etapaVivienda: "Obras Preliminares",
        avanceViviendaPct: 10,
        documentos: []
      };

      setSession(chatId, { type: "ASK_WANT_DOCUMENTS", draft: newBeneficiario });

      return `
Proceso de formulario finalizado.

📄 <b>¿Deseas subir o adjuntar algún documento del beneficiario ahora mismo?</b> (DNI, Copia Literal, Autoavaluo, etc.)

Responder <b>SI / NO</b>:
`.trim();
    }
  }

  // ─── 1.01 ASK WANT DOCUMENTS SESSION ─────────────────────────────────────
  if (currentSession.type === "ASK_WANT_DOCUMENTS") {
    const isYes = norm.includes("si") || norm === "s";
    const b = currentSession.draft as Beneficiario;

    if (isYes) {
      setSession(chatId, { type: "REGISTERING_DOCUMENTS", step: 0, draft: b, docs: [] });
      return `
📎 <b>CARGA DE DOCUMENTACIÓN DIGITAL</b>

📎 Por favor envía el archivo PDF o foto del <b>DNI del Postulante</b> (o escribe <i>"no tengo este documento"</i> para pasar al siguiente):
`.trim();
    } else {
      addBeneficiario(b);
      clearSession(chatId);

      return `
Proceso finalizado.

🎉 <b>¡BENEFICIARIO REGISTRADO CON ÉXITO Y GUARDADO EN EL SISTEMA!</b>

🆔 <b>ID Expediente:</b> <code>${b.id}</code>
👤 <b>Postulante:</b> ${b.postulante}
🪪 <b>DNI:</b> ${b.dniPostulante}
📍 <b>Ubicación:</b> ${b.distrito}, ${b.provincia}, ${b.departamento}
🧭 <b>Coordenadas:</b> X: ${b.coordenadaX || "-"} | Y: ${b.coordenadaY || "-"}
📱 <b>Teléfono:</b> ${b.celular}
🟢 <b>Estado:</b> ${b.estado}

🌐 <i>Guardado en el sistema y visible en el Dashboard Web y Mapa.</i>
`.trim();
    }
  }

  // ─── 1.02 REGISTERING DOCUMENTS WIZARD SESSION ───────────────────────────
  if (currentSession.type === "REGISTERING_DOCUMENTS") {
    const DOC_STEPS = [
      { key: "DNI Postulante", label: "DNI del Postulante" },
      { key: "DNI Cónyuge", label: "DNI del Cónyuge" },
      { key: "DNI Carga Familiar", label: "DNI Carga Familiar" },
      { key: "Copia Literal", label: "Copia Literal SUNARP" },
      { key: "Autoavaluo", label: "Autoavaluo / HR / PU" },
      { key: "Fotografías del Predio", label: "Fotos de la Vivienda / Predio" },
      { key: "Otros Documentos", label: "Otros Documentos Adjuntos" },
    ];

    const stepIndex = currentSession.step;
    const currentDocConfig = DOC_STEPS[stepIndex];
    const b = currentSession.draft as Beneficiario;
    const docsList = currentSession.docs || [];

    const isSkip = norm.includes("no tengo") || norm.includes("no") || norm.includes("omitir") || norm.includes("saltar") || norm.includes("siguiente") || norm.includes("ninguno");

    if (!isSkip) {
      let fileName = text.trim();
      if (fileName.startsWith("[DOCUMENT:") || fileName.startsWith("[PHOTO:")) {
        fileName = fileName.replace(/^\[(DOCUMENT|PHOTO):\s*/, "").replace(/\]$/, "");
      } else if (!fileName.toLowerCase().endsWith(".pdf") && !fileName.toLowerCase().endsWith(".jpg")) {
        fileName = `${currentDocConfig.key}_${b.id}.pdf`;
      }

      const docUrl = fileUrl || createDocumentDataUrl(currentDocConfig.key, b.postulante, fileName);

      docsList.push({
        id: `DOC-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
        tipo: currentDocConfig.key,
        nombre: fileName,
        url: docUrl,
        fecha: new Date().toLocaleDateString("es-PE")
      });
    }

    const nextStepIndex = stepIndex + 1;

    // Filter out DNI Cónyuge if beneficiary has no spouse
    let targetNextIndex = nextStepIndex;
    if (targetNextIndex < DOC_STEPS.length && DOC_STEPS[targetNextIndex].key === "DNI Cónyuge" && !b.tieneConyuge) {
      targetNextIndex++;
    }

    if (targetNextIndex < DOC_STEPS.length) {
      setSession(chatId, { type: "REGISTERING_DOCUMENTS", step: targetNextIndex, draft: b, docs: docsList });
      const nextDocConfig = DOC_STEPS[targetNextIndex];
      return `📎 Por favor envía el archivo PDF o foto de <b>${nextDocConfig.label}</b> (o escribe <i>"no tengo este documento"</i> para pasar al siguiente):`;
    } else {
      b.documentos = docsList;
      addBeneficiario(b);
      clearSession(chatId);

      return `
Proceso finalizado.

🎉 <b>¡BENEFICIARIO Y DOCUMENTACIÓN REGISTRADOS CON ÉXITO!</b>

🆔 <b>ID Expediente:</b> <code>${b.id}</code>
👤 <b>Postulante:</b> ${b.postulante}
🪪 <b>DNI:</b> ${b.dniPostulante}
📄 <b>Archivos Adjuntos:</b> ${docsList.length} documento(s) guardado(s)
📍 <b>Ubicación:</b> ${b.distrito}, ${b.provincia}, ${b.departamento}
📱 <b>Teléfono:</b> ${b.celular}

🌐 <i>Toda la información y archivos están guardados y visibles en el Dashboard Web.</i>
`.trim();
    }
  }

  // ─── 1.1 ACTIVE REGISTERING MAESTRO SESSION ──────────────────────────────
  if (currentSession.type === "REGISTERING_MAESTRO") {
    const stepIndex = currentSession.step;
    const currentStepConfig = MAESTRO_STEPS[stepIndex];
    const val = text.trim();

    const draft = {
      ...currentSession.draft,
      [currentStepConfig.key]: val
    };

    const nextStepIndex = stepIndex + 1;
    if (nextStepIndex < MAESTRO_STEPS.length) {
      setSession(chatId, { type: "REGISTERING_MAESTRO", step: nextStepIndex, draft });
      return `${MAESTRO_STEPS[nextStepIndex].prompt}`;
    } else {
      const count = getMaestros().length + 1;
      const id = `MAE-${String(count).padStart(3, "0")}`;

      let benId = "";
      let benName = "";
      if (draft.beneficiarioAsignadoId && draft.beneficiarioAsignadoId !== "Ninguno") {
        const b = findBeneficiary(draft.beneficiarioAsignadoId);
        if (b) {
          benId = b.id;
          benName = b.postulante;
        }
      }

      const newMaestro: MaestroObra = {
        id,
        nombre: draft.nombre || "Maestro Sin Nombre",
        dni: draft.dni || "00000000",
        celular: draft.celular || "Sin celular",
        especialidad: draft.especialidad || "Albañilería & Estructuras",
        tarifaVivienda: draft.tarifaVivienda || "8000.00",
        beneficiarioAsignadoId: benId,
