    norm.includes("mandar pdf")
  ) {
    const b = findBeneficiary(text);

    if (b) {
      const docs = (b as any).documentos || [];
      const baseUrl = process.env.NEXT_PUBLIC_BASE_URL || "http://localhost:3000";

      // Build document list
      let docList = "";
      if (docs.length > 0) {
        docList = `\n\n📂 <b>Documentos adjuntos (${docs.length}):</b>\n`;
        docs.slice(0, 8).forEach((doc: any, idx: number) => {
          const url = doc.url?.startsWith("http") ? doc.url : `${baseUrl}${doc.url || ""}`;
          docList += `${idx + 1}. 📄 <a href="${url}">${doc.tipo || doc.nombre || "Documento"}</a>\n`;
        });
        if (docs.length > 8) docList += `<i>... y ${docs.length - 8} documentos más. Visita el sistema web para verlos todos.</i>`;
      } else {
        docList = "\n\n📂 <i>Este beneficiario aún no tiene documentos adjuntos.</i>";
      }

      // Ficha link
      const statusBadgeEmoji: Record<string, string> = {
        "Expediente en Revisión": "⚪",
        "Expediente Inscrito": "🟡",
        "Expediente Elegible": "🟢",
        "Expediente No Elegible": "🔴",
        "Expediente con Código de Proyecto": "🟣",
        "Expediente Aprobado": "🔵",
      };
      const estadoEmoji = statusBadgeEmoji[b.estado] || "⚪";

      return `
📋 <b>FICHA DEL BENEFICIARIO — TECHO PROPIO</b>

👤 <b>Postulante:</b> ${b.postulante}
🆔 <b>Expediente:</b> <code>${b.id}</code>
🪪 <b>DNI:</b> <code>${b.dniPostulante || "—"}</code>
📍 <b>Ubicación:</b> ${b.distrito || "—"}, ${b.provincia || "—"}, ${b.departamento || "—"}
🏠 <b>Dirección:</b> ${b.direccion || "—"}
📞 <b>Celular:</b> ${b.celular || "—"}
${estadoEmoji} <b>Estado:</b> ${b.estado || "Expediente en Revisión"}
🏗️ <b>Avance de Obra:</b> ${b.etapaVivienda || "No iniciado"} (${b.avanceViviendaPct || 0}%)
👷 <b>Maestro Asignado:</b> ${b.maestroAsignadoNombre || "Sin asignar"}
${docList}

🌐 <i>Para descargar la Ficha PDF completa, ingresa al sistema web y haz clic en <b>"Descargar Ficha PDF"</b> dentro de la ficha del beneficiario.</i>
`.trim();
    }

    return `📋 <b>ENVIAR FICHA / DOCUMENTOS</b>\n\nPor favor indica el Nombre o DNI del beneficiario. Ejemplo:\n<i>"Enviar ficha de Juan Pérez"</i>\n<i>"Dame los documentos de 76573126"</i>`;
  }

  // ─── 5. INTENT 4: EDITAR / MODIFICAR BENEFICIARIO Y COORDENADAS ───────────
  if (
    norm.includes("editar") ||
    norm.includes("modificar") ||
    norm.includes("actualizar datos") ||
    norm.includes("cambiar datos") ||
    norm.includes("editar ficha") ||
    norm.includes("modificar expediente") ||
    norm.includes("agregar coordenadas") ||
    norm.includes("cambiar coordenadas") ||
    norm.includes("coordenada") ||
    norm.includes("coordenadas") ||
    norm.includes("cordenada") ||
    norm.includes("cordenadas")
  ) {
    const b = findBeneficiary(text);
    if (b) {
      setSession(chatId, { type: "EDITING", targetId: b.id });
      return `
¿Qué dato deseas modificar?

• Nombre
• DNI
• Dirección
• Provincia
• Distrito
• Coordenadas (X / Y)
• Teléfono
• Correo
• Estado
• Licencia de Construcción
• Conformidad de Obra
`.trim();
    }
    return "🔍 Por favor indica el DNI o Nombre del beneficiario que deseas editar (ej. <i>Editar a Juan Pérez</i>).";
  }

  // ─── 6. INTENT 5: ELIMINAR BENEFICIARIO ───────────────────────────────────
  if (
    norm.includes("eliminar beneficiario") ||
    norm.includes("borrar beneficiario") ||
    norm.includes("eliminar expediente") ||
    norm.includes("dar de baja") ||
    norm.includes("eliminar registro")
  ) {
    const b = findBeneficiary(text);
    if (b) {
      setSession(chatId, { type: "CONFIRM_DELETE", targetId: b.id });
      return `
¿Está seguro?

<b>SI / NO</b>
`.trim();
    }
    return "🔍 Indica el nombre o DNI del beneficiario que deseas eliminar (ej. <i>Eliminar a Juan Pérez</i>).";
  }

  // ─── 7. INTENT 6 & 7 & 8: SUBIR / DESCARGAR / LISTAR DOCUMENTOS ────────────
  if (
    norm.includes("subir documento") ||
    norm.includes("subir pdf") ||
    norm.includes("adjuntar pdf") ||
    norm.includes("adjuntar documento") ||
    norm.includes("guardar documento") ||
    norm.includes("guardar pdf") ||
    norm.includes("subir archivo") ||
    norm.includes("subir contrato") ||
    norm.includes("subir dni") ||
    norm.includes("subir plano") ||
    norm.includes("subir acta") ||
    norm.includes("subir voucher")
  ) {
    const b = findBeneficiary(text);
    if (b) {
      setSession(chatId, { type: "WAITING_DOCUMENT_TYPE", targetId: b.id });
      return `
📄 <b>SUBIR DOCUMENTO PDF / ARCHIVO</b>
👤 <b>Beneficiario:</b> ${b.postulante} (Expediente: <code>${b.id}</code>)

Selecciona el <b>tipo de documento</b> que deseas vincular:
1. DNI Postulante
2. DNI Cónyuge
3. DNI Carga Familiar
4. Copia Literal
5. Autoavaluo
6. Fotografías del Predio
7. Otros Documentos
`.trim();
    }

    return "📄 Por favor indica el DNI o Nombre del beneficiario al que deseas subir el documento PDF (ej. <i>Subir documento de Santiago Ramos</i>).";
  }

  if (
    norm.includes("envia") ||
    norm.includes("descargar") ||
    norm.includes("abrir documento") ||
    norm.includes("enviar pdf") ||
    norm.includes("enviar contrato")
  ) {
    const b = findBeneficiary(text);
    return `
Aquí está el documento.

<i>(Archivo PDF / Imagen adjuntado de ${b ? b.postulante : "expediente"})</i>
`.trim();
  }

  if (
    norm.includes("mostrar documentos") ||
    norm.includes("documentos tiene") ||
    norm.includes("listar archivos") ||
    norm.includes("ver documentos")
  ) {
    const b = findBeneficiary(text);
    return `
📁 <b>DOCUMENTOS DE ${b ? b.postulante.toUpperCase() : "EXPEDIENTE"}:</b>

1. 📄 DNI_Postulante.pdf
2. 📜 Contrato_TechoPropio.pdf
3. 📐 Plano_Arquitectura.pdf
4. 🧾 Voucher_Pago.jpg
`.trim();
  }

  // ─── 8.1 INTENT: REGISTRAR NUEVO AVANCE DE OBRA ─────────────────────────
  if (
    norm.includes("registra un nuevo avance") ||
    norm.includes("registrar avance") ||
    norm.includes("nuevo avance de obra") ||
    norm.includes("actualizar avance") ||
    norm.includes("nuevo avance") ||
    norm.includes("avance de obra en la casa") ||
    norm.includes("avance en la casa")
  ) {
    const b = findBeneficiary(text);
    if (b) {
      setSession(chatId, { type: "REGISTERING_AVANCE", targetId: b.id });
      const stagesPromptList = CONSTR_STAGES.map(s => `${s.step}. ${s.name} (${s.pct}%)`).join("\n");
      return `
🏗️ <b>REGISTRAR NUEVO AVANCE DE OBRA</b>
👤 <b>Beneficiario:</b> ${b.postulante} (Expediente: <code>${b.id}</code>)
📍 <b>Etapa Actual:</b> ${b.etapaVivienda || "Obras Preliminares"} (${b.avanceViviendaPct || 10}%)

¿A qué etapa ha avanzado la vivienda? Responde con el número (1 a 7) o nombre:

${stagesPromptList}
`.trim();
    }
    return "🏗️ Por favor indica el Nombre o DNI del beneficiario al que deseas registrar el avance (ej. <i>Registrar nuevo avance de obra en la casa de Santiago Ramos</i>).";
  }

  // ─── 8.2 INTENT: CONSULTAR ESTADO / GRÁFICO DE AVANCE DE OBRA ─────────────
  if (
    norm.includes("avance de obra") ||
    norm.includes("en que avance") ||
    norm.includes("estado de obra") ||
    norm.includes("progreso de obra") ||
    norm.includes("como va la vivienda") ||
    norm.includes("en que etapa esta")
  ) {
    const b = findBeneficiary(text);
    if (b) {
      const pct = b.avanceViviendaPct || 10;
      const currentEtapa = b.etapaVivienda || "Obras Preliminares & Trazo";
      const filled = Math.round((pct / 100) * 10);
      const empty = 10 - filled;
      const progressBar = "█".repeat(filled) + "░".repeat(empty);

      const stageChart = CONSTR_STAGES.map(st => {
        if (st.pct < pct) return `✅ ${st.step}. ${st.name} (${st.pct}%)`;
        if (st.pct === pct || normalizeText(st.name).includes(normalizeText(currentEtapa))) {
          return `🔄 <b>${st.step}. ${st.name} (${st.pct}%)</b> ⬅️ <i>[Etapa Actual]</i>`;
        }
        return `⏳ ${st.step}. ${st.name} (${st.pct}%)`;
      }).join("\n");

      return `
🏗️ <b>ESTADO DE AVANCE DE OBRA — ${b.postulante.toUpperCase()}</b>
🆔 <b>Expediente:</b> <code>${b.id}</code> | 🪪 <b>DNI:</b> ${b.dniPostulante}
📍 <b>Ubicación:</b> ${b.distrito}, ${b.provincia}, ${b.departamento}

📊 <b>Progreso General:</b> [<code>${progressBar}</code>] <b>${pct}%</b>

${stageChart}

👷‍♂️ <b>Maestro Asignado:</b> ${b.maestroAsignadoNombre || "Sin asignar"}
`.trim();
    }
    return "🏗️ Indica el nombre o DNI del beneficiario para consultar su gráfico de avance (ej. <i>Quiero saber en qué avance de obra está la vivienda de Santiago Ramos</i>).";
  }

  // ─── 8.3 INTENT: ASIGNAR MAESTRO DE OBRA A BENEFICIARIO / DISTRITO ───────
  if (
    norm.includes("asignes a los beneficiarios") ||
    norm.includes("asigna a los beneficiarios") ||
    norm.includes("asigna al beneficiario") ||
    norm.includes("asignar maestro") ||
    norm.includes("asigna al maestro") ||
    norm.includes("vincular maestro")
  ) {
    const maestros = getMaestros();
    if (maestros.length === 0) {
      return "⚠️ No hay maestros de obra registrados aún. Escribe <i>'Registrar nuevo maestro'</i> para crear uno.";
    }

    let targetMaestro = maestros.find(m => norm.includes(normalizeText(m.nombre)) || norm.includes(normalizeText(m.id)));
    if (!targetMaestro) targetMaestro = maestros[0];

    const allB = getBeneficiarios();
    let targetBeneficiaries: Beneficiario[] = [];

    const locationTokens = norm.replace(/.*(beneficiarios|asignes|asigna)\s+(de|del|en)?\s+/, "").trim();
    const locationMatches = allB.filter(b => 
      normalizeText(b.distrito).includes(locationTokens) ||
      normalizeText(b.provincia).includes(locationTokens) ||
      normalizeText(b.departamento).includes(locationTokens)
    );

    if (locationMatches.length > 0) {
      targetBeneficiaries = locationMatches;
    } else {
      const singleB = findBeneficiary(text);
      if (singleB) targetBeneficiaries = [singleB];
    }

    if (targetBeneficiaries.length === 0) {
      targetBeneficiaries = allB;
    }

    const ids = targetBeneficiaries.map(b => b.id);
    const count = assignMaestroToBeneficiarios(targetMaestro.id, targetMaestro.nombre, ids);

    return `
👷‍♂️ <b>¡MAESTRO DE OBRA ASIGNADO CON ÉXITO!</b>

👷‍♂️ <b>Maestro:</b> ${targetMaestro.nombre} (ID: <code>${targetMaestro.id}</code>)
📌 <b>Beneficiarios Asignados:</b> ${count} vivienda(s)
👥 <b>Lista:</b> ${targetBeneficiaries.slice(0, 5).map(b => b.postulante).join(", ")}${targetBeneficiaries.length > 5 ? "..." : ""}

🌐 <i>Guardado y sincronizado en el Cronograma de Obra Web.</i>
`.trim();
  }

  // ─── 9. INTENT 11 & 12: CRONOGRAMA DE PAGOS Y REGISTRAR DESEMBOLSO ────────
  if (
    norm.includes("pagos") ||
    norm.includes("desembolsos") ||
    norm.includes("financiero") ||
    norm.includes("desembolso") ||
    norm.includes("registrar pago")
  ) {
    return `
💰 <b>CRONOGRAMA DE PAGOS & DESEMBOLSOS</b>

• <b>1er Desembolso:</b> S/ 15,000.00 (Desembolsado)
• <b>2do Desembolso:</b> S/ 20,000.00 (En trámite)
• <b>3er Desembolso:</b> S/ 15,000.00 (Pendiente)
• <b>Próximo desembolso:</b> 25/08/2026
`.trim();
  }

  // ─── 10. INTENT 13 & 14: CONSULTA DE MAESTROS DE OBRA ─────────────────────
  if (norm.includes("maestro") || norm.includes("construye")) {
    const b = findBeneficiary(text);
    const maestros = getMaestros();

    if (b && b.maestroAsignadoNombre) {
      return `
👷‍♂️ <b>MAESTRO ASIGNADO — ${b.postulante.toUpperCase()}</b>

• <b>Maestro:</b> ${b.maestroAsignadoNombre}
• <b>Expediente:</b> ${b.id} (${b.distrito})
🌐 <i>Asignado en el sistema.</i>
`.trim();
    }

    if (maestros.length > 0) {
      let mText = `👷‍♂️ <b>MAESTROS DE OBRA REGISTRADOS:</b> (${maestros.length})\n\n`;
      maestros.forEach((m, idx) => {
        mText += `${idx + 1}. <b>${m.nombre}</b> (ID: <code>${m.id}</code>) — DNI: ${m.dni} | Cel: ${m.celular}\n🔨 Especialidad: ${m.especialidad} | 💰 S/ ${m.tarifaVivienda}\n\n`;
      });
      return mText.trim();
    }

    return `
👷‍♂️ <b>MAESTROS DE OBRA</b>

No hay maestros de obra registrados aún. Escribe <i>"Registrar nuevo maestro"</i> para crear uno.
`.trim();
  }

  // ─── 11. INTENT 15 & 16: REPORTES Y FILTROS ───────────────────────────────
  const allBeneficiarios = getBeneficiarios();

  if (norm.includes("beneficiarios de") || norm.includes("expedientes de")) {
    const place = norm.replace(/.*(beneficiarios|expedientes) de\s+/, "").trim();
    const filtered = allBeneficiarios.filter(b =>
      normalizeText(b.distrito).includes(place) ||
      normalizeText(b.provincia).includes(place) ||
      normalizeText(b.departamento).includes(place)
    );

    if (filtered.length > 0) {
      let listText = `📍 <b>BENEFICIARIOS DE ${place.toUpperCase()}:</b> (${filtered.length})\n\n`;
      filtered.forEach((b, idx) => {
        listText += `${idx + 1}. <b>${b.postulante}</b> — DNI: ${b.dniPostulante} (${b.distrito})\n`;
      });
      return listText.trim();
    }
    return `📍 No se encontraron beneficiarios registrados en "${place.toUpperCase()}".`;
  }

  // ─── 12. INTENT 3 & 2: CONSULTAS RÁPIDAS Y FICHA ──────────────────────────
  const bFound = findBeneficiary(text);

  if (norm.includes("dni")) {
    if (bFound) return `🪪 <b>DNI:</b> <code>${bFound.dniPostulante}</code> (${bFound.postulante})`;
  }
  if (norm.includes("telefono") || norm.includes("celular")) {
    if (bFound) return `📱 <b>Teléfono:</b> ${bFound.celular} (${bFound.postulante})`;
  }
  if (norm.includes("correo") || norm.includes("email")) {
    if (bFound) return `📧 <b>Correo:</b> ${bFound.correo || "No registrado"} (${bFound.postulante})`;
  }
  if (norm.includes("direccion") || norm.includes("donde vive") || norm.includes("ubicacion")) {
    if (bFound) return `📍 <b>Dirección:</b> ${bFound.direccion} (${bFound.distrito}, ${bFound.departamento})`;
  }
  if (norm.includes("departamento")) {
    if (bFound) return `📍 <b>Departamento:</b> ${bFound.departamento} (${bFound.postulante})`;
  }
  if (norm.includes("provincia")) {
    if (bFound) return `📍 <b>Provincia:</b> ${bFound.provincia} (${bFound.postulante})`;
  }
  if (norm.includes("distrito")) {
    if (bFound) return `📍 <b>Distrito:</b> ${bFound.distrito} (${bFound.postulante})`;
  }
  if (norm.includes("estado")) {
    if (bFound) return `🟢 <b>Estado:</b> <b>${bFound.estado}</b> (${bFound.postulante})`;
  }

  if (bFound) {
    if (norm.includes("descarga") || norm.includes("descargar") || norm.includes("quiero la ficha") || norm.includes("imprimir")) {
      return `
📄 <b>FICHA DE BENEFICIARIO GENERADA</b>

👤 <b>Postulante:</b> ${bFound.postulante}
🆔 <b>Expediente:</b> <code>${bFound.id}</code>
📍 <b>Ubicación:</b> ${bFound.distrito}, ${bFound.departamento}

⬇️ <b>Documento PDF Listo para Descargar:</b>
<a href="http://localhost:3000" style="color: #38bdf8; text-decoration: underline;">📄 Descargar_Ficha_Beneficiario_${bFound.id}.pdf</a>

<i>*Haz clic en el enlace para descargar el documento oficial.</i>
`.trim();
    }

    return `
📄 <b>FICHA DE ${bFound.postulante.toUpperCase()}</b>

🆔 <b>Expediente:</b> <code>${bFound.id}</code>
👤 <b>Postulante:</b> ${bFound.postulante}
🪪 <b>DNI:</b> ${bFound.dniPostulante || "Sin DNI"}
📱 <b>Teléfono:</b> ${bFound.celular || "Sin teléfono"}
📧 <b>Correo:</b> ${bFound.correo || "N/A"}

📍 <b>UBICACIÓN:</b>
• <b>Departamento:</b> ${bFound.departamento}
• <b>Provincia:</b> ${bFound.provincia}
• <b>Distrito:</b> ${bFound.distrito}
• <b>Dirección:</b> ${bFound.direccion}
🧭 <b>Coordenadas:</b> X: ${bFound.coordenadaX || "-"} | Y: ${bFound.coordenadaY || "-"}

🏗️ <b>OBRA:</b>
• <b>Etapa:</b> ${bFound.etapaVivienda || "Cimentación"} (${bFound.avanceViviendaPct || 40}%)
• <b>Maestro:</b> Carlos Ríos Pérez

🟢 <b>Estado:</b> <b>${bFound.estado}</b>
`.trim();
  }

  // ─── 12.5. INTENT: DESCARGAR FICHA MAESTRO ────────────────────────
  if (norm.includes("quiero la ficha") || norm.includes("descarga") || norm.includes("descargar")) {
    if (norm.includes("maestro")) {
      const queryName = text.toLowerCase().replace(/quiero la ficha de(l)? maestro/g, "").replace(/descarga(r)? ficha de(l)? maestro/g, "").trim();
      const maestros = getMaestros();
      const mFound = maestros.find(m => normalizeText(m.nombre).includes(normalizeText(queryName)));

      if (mFound) {
        return `
📄 <b>FICHA DE MAESTRO DE OBRA GENERADA</b>

👤 <b>Maestro:</b> ${mFound.nombre}
🪪 <b>DNI:</b> ${mFound.dni}
🔨 <b>Especialidad:</b> ${mFound.especialidad}

⬇️ <b>Documento PDF Listo para Descargar:</b>
<a href="http://localhost:3000" style="color: #38bdf8; text-decoration: underline;">📄 Descargar_Ficha_Maestro_${mFound.id}.pdf</a>

<i>*Haz clic en el enlace para descargar el documento oficial.</i>
`.trim();
      } else {
        return `⚠️ No se encontró al maestro "${queryName}".`;
      }
    }
  }

  // ─── 13. INTENT 20: ESTADÍSTICAS GENERALES ────────────────────────────────
  if (norm.includes("cuantos") || norm.includes("estadisticas") || norm.includes("reporte")) {
    const list = getBeneficiarios();
    return `
📊 <b>ESTADÍSTICAS GENERALES</b>

• <b>Beneficiarios:</b> ${list.length}
• <b>Expedientes:</b> ${list.length}
• <b>Viviendas:</b> ${list.length}
• <b>Maestros:</b> 3
`.trim();
  }

  // Fallback response / Ayuda / Menu
  return `
🤖 <b>Asistente Techo Propio</b>

Entendí tu consulta sobre: "<b>${text}</b>".

<b>MENU DE OPCIONES - ¿QUÉ PUEDO HACER?</b> 📋

1️⃣ <b>Gestión de Beneficiarios:</b>
• <i>"Registrar nuevo beneficiario"</i> (Inicia formulario)
• <i>"Editar beneficiario [Nombre]"</i> (Modificar datos)
• <i>"Cambiar estado de [Nombre] a Expediente Aprobado"</i>
• <i>"Subir archivo a [Nombre]"</i> (Adjuntar documentos)

2️⃣ <b>Gestión de Maestros de Obra:</b>
• <i>"Registrar nuevo maestro"</i> (Inicia formulario)
• <i>"Asignar maestro [Nombre] a beneficiario [Nombre]"</i>

3️⃣ <b>Descarga de Fichas Oficiales (PDF):</b>
• <i>"Quiero la ficha de [Nombre Beneficiario]"</i> (Descarga Ficha Beneficiario)
• <i>"Quiero la ficha de maestro [Nombre Maestro]"</i> (Descarga Ficha Maestro)

4️⃣ <b>Consultas de Obra y Pagos:</b>
• <i>"¿En qué etapa está la vivienda de [Nombre]?"</i>
• <i>"Actualizar avance de [Nombre]"</i>
• <i>"Consultar cronograma de pagos"</i>

5️⃣ <b>Consultas Rápidas:</b>
• <i>"Muéstrame la ficha de [Nombre]"</i> (Ver datos en texto)
• <i>"DNI de [Nombre]"</i> / <i>"Dirección de [Nombre]"</i>

<i>💡 Solo escribe una de las opciones o pide "Ayuda" para ver este menú.</i>
`.trim();
}

import fs from "fs";
import path from "path";
import { Beneficiario } from "../app/types";

export type SessionState =
  | { type: "IDLE" }
  | { type: "REGISTERING"; step: number; draft: Partial<Beneficiario> }
  | { type: "ASK_WANT_DOCUMENTS"; draft: Partial<Beneficiario> }
  | { type: "REGISTERING_DOCUMENTS"; step: number; draft: Partial<Beneficiario>; docs: any[] }
  | { type: "EDITING"; targetId: string; lastField?: string }
  | { type: "CONFIRM_DELETE"; targetId: string }
  | { type: "WAITING_DOCUMENT_TYPE"; targetId: string }
  | { type: "WAITING_DOCUMENT_FILE"; targetId: string; docType: string }
  | { type: "REGISTERING_MAESTRO"; step: number; draft: { nombre?: string; dni?: string; celular?: string; especialidad?: string; tarifaVivienda?: string; beneficiarioAsignadoId?: string; beneficiarioAsignadoNombre?: string } }
  | { type: "REGISTERING_AVANCE"; targetId: string }
